/* DAWAH X — ahmad, অধ্যায় 58 · খণ্ড 58 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][58]=[[11401,11401,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏قَزَعَةَ بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَالَ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ قَالَ اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ أَهْلَ الثَّنَاءِ وَالْمَجْدِ أَحَقُّ مَا قَالَ الْعَبْدُ وَكُلُّنَا لَكَ عَبْدٌ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا يَنْفَعُ ذَا ‏ ‏الْجَدِّ ‏ ‏مِنْكَ ‏ ‏الْجَدُّ ‏","","",""],[11402,11402,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمُتَحَابِّينَ ‏ ‏لَتُرَى غُرَفُهُمْ فِي الْجَنَّةِ كَالْكَوْكَبِ الطَّالِعِ الشَّرْقِيِّ أَوْ الْغَرْبِيِّ فَيُقَالُ مَنْ هَؤُلَاءِ فَيُقَالُ هَؤُلَاءِ الْمُتَحَابُّونَ فِي اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[11403,11403,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا شَكَّ أَحَدُكُمْ فِي صَلَاتِهِ فَلْيُلْقِ الشَّكَّ وَلْيَبْنِ عَلَى الْيَقِينِ وَلْيُصَلِّ سَجْدَتَيْنِ فَإِنْ كَانَتْ خَمْسًا ‏ ‏شَفَعَ ‏ ‏بِهِمَا وَإِنْ كَانَ صَلَّى أَرْبَعًا كَانَتَا تَرْغِيمًا لِلشَّيْطَانِ ‏","","",""],[11404,11404,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا لَا يَمْنَعَنَّ أَحَدَكُمْ مَخَافَةُ النَّاسِ أَنْ يَقُولَ الْحَقَّ إِذَا رَآهُ ‏","","",""],[11405,11405,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خُلَيْدِ بْنِ جَعْفَرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏ذُكِرَ الْمِسْكُ ‏ ‏عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَوَلَيْسَ مِنْ أَطْيَبِ الطِّيبِ ‏","","",""],[11406,11406,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشَدَّ حَيَاءً مِنْ عَذْرَاءَ فِي ‏ ‏خِدْرِهَا ‏ ‏وَكَانَ إِذَا كَرِهَ شَيْئًا عَرَفْنَاهُ فِي وَجْهِهِ ‏","","",""],[11407,11407,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا اسْتُخْلِفَ مِنْ خَلِيفَةٍ إِلَّا كَانَتْ لَهُ ‏ ‏بِطَانَتَانِ ‏ ‏بِطَانَةٌ ‏ ‏تَأْمُرُهُ بِالْخَيْرِ وَتَحُضُّهُ عَلَيْهِ ‏ ‏وَبِطَانَةٌ ‏ ‏تَأْمُرُهُ بِالشَّرِّ وَتَحُضُّهُ عَلَيْهِ فَالْمَعْصُومُ مَنْ ‏ ‏عَصَمَ ‏ ‏اللَّهُ ‏","","",""],[11408,11408,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ يَقُولُ لِأَهْلِ الْجَنَّةِ يَا أَهْلَ الْجَنَّةِ فَيَقُولُونَ لَبَّيْكَ رَبَّنَا وَسَعْدَيْكَ فَيَقُولُ هَلْ رَضِيتُمْ فَيَقُولُونَ وَمَا لَنَا لَا ‏ ‏نَرْضَى وَقَدْ أَعْطَيْتَنَا مَا لَمْ تُعْطِ أَحَدًا مِنْ خَلْقِكَ فَيَقُولُ أَنَا أُعْطِيكُمْ أَفْضَلَ مِنْ ذَلِكَ قَالُوا يَا رَبَّنَا فَأَيُّ شَيْءٍ أَفْضَلُ مِنْ ذَلِكَ قَالَ أُحِلُّ عَلَيْكُمْ رِضْوَانِي فَلَا أَسْخَطُ بَعْدَهُ أَبَدًا ‏","","",""],[11409,11409,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ يَزِيدَ أَبُو شُجَاعٍ ‏ ‏عَنْ ‏ ‏أَبِي السَّمْحِ ‏ ‏عَنْ ‏ ‏أَبِي الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ { ‏وَهُمْ فِيهَا ‏ ‏كَالِحُونَ ‏ } ‏قَالَ ‏ ‏تَشْوِيهِ النَّارُ ‏ ‏فَتَقَلَّصُ شَفَتُهُ الْعُلْيَا حَتَّى تَبْلُغَ وَسَطَ رَأْسِهِ ‏ ‏وَتَسْتَرْخِي شَفَتُهُ السُّفْلَى حَتَّى تَضْرِبَ سُرَّتَهُ ‏","","",""],[11410,11410,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ شُعَيْبِ بْنِ أَبِي حَمْزَةَ ‏ ‏أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ يَعْنِي الزُّهْرِيَّ ‏ ‏أَخْبَرَنِي ‏ ‏حُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏وَأَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏أَخْبَرَاهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏نُخَامَةً ‏ ‏فِي حَائِطِ الْمَسْجِدِ فَتَنَاوَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَصَاةً ‏ ‏فَحَتَّهَا ‏ ‏ثُمَّ قَالَ ‏ ‏إِذَا ‏ ‏تَنَخَّمَ ‏ ‏أَحَدُكُمْ وَهُوَ ‏ ‏يُصَلِّي فَلَا ‏ ‏يَتَنَخَّمْ ‏ ‏قِبَلَ وَجْهِهِ وَلَا عَنْ يَمِينِهِ وَلْيَبْصُقْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ الْيُسْرَى ‏","","",""],[11411,11411,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏عَطَاءُ بْنُ يَزِيدَ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏أَنَّهُ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ أَيُّ النَّاسِ أَفْضَلُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُؤْمِنٌ يُجَاهِدُ فِي سَبِيلِ اللَّهِ بِنَفْسِهِ وَمَالِهِ فَقَالُوا ثُمَّ مَنْ قَالَ مُؤْمِنٌ فِي ‏ ‏شِعْبٍ ‏ ‏مِنْ ‏ ‏الشِّعَابِ ‏ ‏يَتَّقِي اللَّهَ وَيَدَعُ النَّاسَ مِنْ شَرِّهِ ‏","","",""],[11412,11412,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَنْبَأَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَيْرِيزٍ الْجُمَحِيُّ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ بَيْنَا هُوَ جَالِسٌ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّا نُصِيبُ ‏ ‏سَبْيًا ‏ ‏فَنُحِبُّ الْإِثْمَانَ فَكَيْفَ ‏ ‏تَرَى فِي ‏ ‏الْعَزْلِ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّكُمْ لَتَفْعَلُونَ ذَلِكُمْ لَا عَلَيْكُمْ أَنْ لَا تَفْعَلُوا ذَلِكُمْ فَإِنَّهَا لَيْسَتْ نَسَمَةٌ كَتَبَ اللَّهُ أَنْ تَخْرُجَ إِلَّا هِيَ خَارِجَةٌ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَوْزاعِيِّ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ النَّاسِ أَفْضَلُ ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏شُعَيْبٍ ‏","","",""],[11413,11413,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي حُسَيْنٍ ‏ ‏حَدَّثَنِي ‏ ‏شَهْرٌ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏حَدَّثَهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ بَيْنَا أَعْرَابِيٌّ فِي بَعْضِ نَوَاحِي ‏ ‏الْمَدِينَةِ ‏ ‏فِي غَنَمٍ لَهُ عَدَا عَلَيْهِ الذِّئْبُ فَأَخَذَ شَاةً مِنْ غَنَمِهِ فَأَدْرَكَهُ الْأَعْرَابِيُّ فَاسْتَنْقَذَهَا مِنْهُ وَهَجْهَجَهُ فَعَانَدَهُ الذِّئْبُ يَمْشِي ثُمَّ ‏ ‏أَقْعَى ‏ ‏مُسْتَذْفِرًا ‏ ‏بِذَنَبِهِ يُخَاطِبُهُ فَقَالَ أَخَذْتَ رِزْقًا رَزَقَنِيهِ اللَّهُ قَالَ وَاعَجَبًا مِنْ ذِئْبٍ ‏ ‏مُقْعٍ ‏ ‏مُسْتَذْفِرٍ ‏ ‏بِذَنَبِهِ يُخَاطِبُنِي فَقَالَ وَاللَّهِ إِنَّكَ لَتَتْرُكُ أَعْجَبَ مِنْ ذَلِكَ قَالَ وَمَا أَعْجَبُ مِنْ ذَلِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏النَّخْلَتَيْنِ ‏ ‏بَيْنَ ‏ ‏الْحَرَّتَيْنِ ‏ ‏يُحَدِّثُ النَّاسَ عَنْ نَبَإِ مَا قَدْ سَبَقَ وَمَا يَكُونُ بَعْدَ ‏ ‏ذَلِكَ قَالَ فَنَعَقَ الْأَعْرَابِيُّ بِغَنَمِهِ حَتَّى أَلْجَأَهَا إِلَى بَعْضِ ‏ ‏الْمَدِينَةِ ‏ ‏ثُمَّ مَشَى إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى ضَرَبَ عَلَيْهِ بَابَهُ فَلَمَّا صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَيْنَ الْأَعْرَابِيُّ صَاحِبُ الْغَنَمِ فَقَامَ الْأَعْرَابِيُّ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِّثْ النَّاسَ بِمَا سَمِعْتَ وَمَا رَأَيْتَ فَحَدَّثَ الْأَعْرَابِيُّ النَّاسَ بِمَا رَأَى مِنْ الذِّئْبِ وَسَمِعَ مِنْهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ ذَلِكَ صَدَقَ آيَاتٌ تَكُونُ قَبْلَ السَّاعَةِ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَخْرُجَ أَحَدُكُمْ مِنْ أَهْلِهِ فَتُخْبِرَهُ نَعْلُهُ أَوْ سَوْطُهُ أَوْ عَصَاهُ بِمَا أَحْدَثَ أَهْلُهُ بَعْدَهُ ‏","","",""],[11414,11414,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْفُضَيْلُ بْنُ مَرْزُوقٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ ‏ ‏رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏لِأَصْحَابِهِ أَمَا وَاللَّهِ لَقَدْ كُنْتُ أُحَدِّثُكُمْ أَنَّهُ لَوْ قَدْ اسْتَقَامَتْ الْأُمُورُ قَدْ آثَرَ عَلَيْكُمْ قَالَ فَرَدُّوا عَلَيْهِ رَدًّا عَنِيفًا قَالَ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَجَاءَهُمْ فَقَالَ لَهُمْ أَشْيَاءَ لَا أَحْفَظُهَا قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ فَكُنْتُمْ لَا تَرْكَبُونَ الْخَيْلَ قَالَ فَكُلَّمَا قَالَ لَهُمْ شَيْئًا قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ فَلَمَّا رَآهُمْ لَا يَرُدُّونَ عَلَيْهِ شَيْئًا قَالَ أَفَلَا تَقُولُونَ قَاتَلَكَ قَوْمُكَ فَنَصَرْنَاكَ وَأَخْرَجَكَ قَوْمُكَ فَآوَيْنَاكَ قَالُوا نَحْنُ لَا نَقُولُ ذَلِكَ يَا رَسُولَ اللَّهِ أَنْتَ تَقُولُهُ قَالَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏أَلَا تَرْضَوْنَ أَنْ يَذْهَبَ النَّاسُ بِالدُّنْيَا وَتَذْهَبُونَ أَنْتُمْ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏أَلَا تَرْضَوْنَ أَنَّ النَّاسَ لَوْ سَلَكُوا وَادِيًا وَسَلَكْتُمْ وَادِيًا لَسَلَكْتُ وَادِيَ ‏ ‏الْأَنْصَارِ ‏ ‏قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ ‏ ‏لَوْلَا الْهِجْرَةُ لَكُنْتُ امْرَأً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏كَرِشِي ‏ ‏وَأَهْلُ بَيْتِي ‏ ‏وَعَيْبَتِي ‏ ‏الَّتِي آوِي إِلَيْهَا فَاعْفُوا عَنْ مُسِيئِهِمْ وَاقْبَلُوا مِنْ مُحْسِنِهِمْ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏قُلْتُ ‏ ‏لِمُعَاوِيَةَ ‏ ‏أَمَا إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا أَنَّنَا ‏ ‏سَنَرَى بَعْدَهُ ‏ ‏أَثَرَةً ‏ ‏قَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏فَمَا أَمَرَكُمْ قُلْتُ أَمَرَنَا أَنْ نَصْبِرَ قَالَ فَاصْبِرُوا إِذًا ‏","","",""],[11415,11415,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَتَتَّبِعُنَّ سُنَنَ الَّذِينَ مِنْ قَبْلِكُمْ شِبْرًا بِشِبْرٍ وَذِرَاعًا بِذِرَاعٍ حَتَّى لَوْ دَخَلُوا جُحْرَ ضَبٍّ لَتَبِعْتُمُوهُمْ قُلْنَا يَا رَسُولَ اللَّهِ ‏ ‏الْيَهُودُ ‏ ‏وَالنَّصَارَى ‏ ‏قَالَ فَمَنْ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏حَدَّثَنِي ‏ ‏شَهْرٌ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَجُلٌ مِنْ ‏ ‏أَسْلَمَ ‏ ‏فِي غُنَيْمَةٍ لَهُ يَهُشُّ عَلَيْهَا فِي ‏ ‏بَيْداءِ ذِي الْحُلَيْفَةِ ‏ ‏إِذْ عَدَا عَلَيْهِ ذِئْبٌ فَانْتَزَعَ شَاةً مِنْ غَنَمِهِ ‏ ‏فَجَهْجَأَهُ ‏ ‏الرَّجُلُ فَرَمَاهُ بِالْحِجَارَةِ حَتَّى اسْتَنْقَذَ مِنْهُ شَاتَهُ ثُمَّ إِنَّ الذِّئْبَ أَقْبَلَ حَتَّى ‏ ‏أَقْعَى ‏ ‏مُسْتَذْفِرًا ‏ ‏بِذَنَبِهِ مُقَابِلَ الرَّجُلِ ‏ ‏فَذَكَرَهُ ‏ ‏نَحْوَ حَدِيثِ ‏ ‏شُعَيْبِ بْنِ أَبِي حَمْزَةَ ‏","","",""],[11416,11416,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْرَائِيلَ إِسْمَاعِيلُ الْمُلَائِيُّ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وُجِدَ قَتِيلٌ بَيْنَ قَرْيَتَيْنِ ‏ ‏أَوْ مَيِّتٌ ‏ ‏فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذُرِعَ مَا بَيْنَ الْقَرْيَتَيْنِ إِلَى أَيِّهِمَا كَانَ أَقْرَبَ فَوُجِدَ أَقْرَبَ إِلَى أَحَدِهِمَا بِشِبْرٍ قَالَ فَكَأَنِّي أَنْظُرُ إِلَى شِبْرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَعَلَهُ عَلَى الَّذِي كَانَ أَقْرَبَ ‏","","",""],[11417,11417,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ أَبِي أَنَسٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏و حَدَّثَنَاه ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ ‏ ‏عِمْرَانُ بْنُ أَبِي أَنَسٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏تَمَارَى ‏ ‏رَجُلَانِ فِي الْمَسْجِدِ الَّذِي أُسِّسَ عَلَى التَّقْوَى فَقَالَ أَحَدُهُمَا هُوَ ‏ ‏مَسْجِدُ قُبَاءٍ ‏ ‏وَقَالَ الْآخَرُ هُوَ ‏ ‏مَسْجِدُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ ‏ ‏مَسْجِدِي ‏ ‏هَذَا ‏","","",""],[11418,11418,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏وَأَبُو عَامِرٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏أَبُو عَامِرٍ ‏ ‏عَنْ ‏ ‏أَبِي إِبْرَاهِيمَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابَهُ حَلَّقُوا رُءُوسَهُمْ عَامَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏غَيْرَ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏وَأَبِي قَتَادَةَ ‏ ‏فَاسْتَغْفَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْمُحَلِّقِينَ ثَلَاثَ مِرَارٍ وَلِلْمُقَصِّرِينَ مَرَّةً ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏أَنَّ ‏ ‏أَبَا إِبْرَاهِيمَ الْأَنْصَارِيَّ ‏ ‏مِنْ ‏ ‏بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏أَبَا سَعِيدٍ ‏ ‏قَالَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[11419,11419,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ خَلِيطِ الزَّبِيبِ وَالتَّمْرِ ‏ ‏وَالْبُسْرِ ‏ ‏وَالتَّمْرِ ‏","","",""],[11420,11420,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَمُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَا ثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَأَنْ يُخْلَطَ بَيْنَ الزَّبِيبِ وَالتَّمْرِ ‏ ‏وَالْبُسْرِ ‏ ‏وَالتَّمْرِ ‏","","",""],[11421,11421,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَأَنْ يُخْلَطَ بَيْنَ الزَّبِيبِ وَالتَّمْرِ ‏ ‏وَالْبُسْرِ ‏ ‏وَالتَّمْرِ ‏","","",""],[11422,11422,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ ثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَقَالَ ‏ ‏انْتَبِذْ ‏ ‏فِي ‏ ‏سِقَائِكَ ‏ ‏وَأَوْكِهِ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنِي ‏ ‏مَنْ لَقِيَ ‏ ‏الْوَفْدَ الَّذِينَ قَدِمُوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏عَبْدِ الْقَيْسِ ‏ ‏فِيهِمْ ‏ ‏الْأَشَجُّ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ إِنَّا حَيٌّ مِنْ ‏ ‏رَبِيعَةَ ‏ ‏وَبَيْنَنَا وَبَيْنَكَ كُفَّارُ ‏ ‏مُضَرَ ‏ ‏فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏يَحْيَى ‏ ‏وَلَمْ يَذْكُرْ أَنَّ فِيكَ ‏ ‏خَلَّتَيْنِ ‏","","",""],[11423,11423,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمُثَنَّى الْقَصِيرُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُتَوَكِّلِ النَّاجِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏نَهَى نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الشُّرْبِ فِي ‏ ‏الْحَنْتَمَةِ ‏ ‏وَالدُّبَّاءِ ‏ ‏وَالنَّقِيرِ ‏","","",""],[11424,11424,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَيَخْرُجُ نَاسٌ مِنْ النَّارِ قَدْ احْتَرَقُوا وَكَانُوا مِثْلَ الْحُمَمِ ثُمَّ لَا يَزَالُ أَهْلُ الْجَنَّةِ يَرُشُّونَ عَلَيْهِمْ الْمَاءَ حَتَّى يَنْبُتُونَ نَبَاتَ ‏ ‏الْغُثَاءِ ‏ ‏فِي السَّيْلِ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ سَيَخْرُجُ نَاسٌ مِنْ النَّارِ ‏ ‏فَذَكَرَهُ ‏","","",""],[11425,11425,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَخْرُجُ ‏ ‏ضُبَارَةٌ ‏ ‏مِنْ النَّارِ قَدْ كَانُوا فَحْمًا قَالَ فَيُقَالُ بُثُّوهُمْ فِي الْجَنَّةِ وَرُشُّوا عَلَيْهِمْ مِنْ الْمَاءِ قَالَ فَيَنْبُتُونَ كَمَا تَنْبُتُ الْحِبَّةُ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ فَقَالَ رَجُلٌ مِنْ الْقَوْمِ كَأَنَّكَ كُنْتَ مِنْ أَهْلِ الْبَادِيَةِ يَا رَسُولَ اللَّهِ ‏","","",""],[11426,11426,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏أَنَّ ‏ ‏رَافِعَ بْنَ إِسْحَاقَ ‏ ‏أَخْبَرَهُ ‏ ‏قَالَ ‏ ‏دَخَلْتُ أَنَا ‏ ‏وَعَبْدُ اللَّهِ بْنُ أَبِي طَلْحَةَ ‏ ‏عَلَى ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏نَعُودُهُ ‏ ‏فَقَالَ ‏ ‏لَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَخْبَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ الْمَلَائِكَةَ لَا تَدْخُلُ بَيْتًا فِيهِ تَمَاثِيلُ ‏ ‏أَوْ صُورَةٌ شَكَّ ‏ ‏إِسْحَاقُ ‏ ‏لَا يَدْرِي أَيَّتَهُمَا قَالَ ‏ ‏أَبُو سَعِيدٍ ‏","","",""],[11427,11427,"","","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ مَخْلَدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ جَعْفَرٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عُمَيْرٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏جَلَسْتُ إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏وَأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏فَقَالَ ‏ ‏أَحَدُهُمَا لِصَاحِبِهِ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ أَنَّهُ ‏ ‏يَبْلُغُ الْعَرَقُ مِنْ النَّاسِ يَوْمَ الْقِيَامَةِ ‏ ‏فَقَالَ ‏ ‏أَحَدُهُمَا إِلَى شَحْمَتِهِ ‏ ‏وَقَالَ ‏ ‏الْآخَرُ ‏ ‏يُلْجِمُهُ ‏ ‏فَخَطَّ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَأَشَارَ ‏ ‏أَبُو عَاصِمٍ ‏ ‏بِأُصْبُعِهِ ‏ ‏مِنْ أَسْفَلِ شَحْمَةِ أُذُنَيْهِ إِلَى ‏ ‏فِيهِ فَقَالَ مَا أَرَى ذَاكَ إِلَّا سَوَاءً ‏","","",""],[11428,11428,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏وَيُونُسُ بْنُ يَزِيدَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعْتُمْ الْمُؤَذِّنَ ‏ ‏وَقَالَ ‏ ‏مَالِكٌ ‏ ‏الْمُنَادِيَ ‏ ‏فَقُولُوا مِثْلَ يَقُولُ ‏ ‏زَادَ ‏ ‏مَالِكٌ ‏ ‏الْمُؤَذِّنَ ‏","","",""],[11429,11429,"","","‏ ‏حَدَّثَنَا ‏ ‏مَحْبُوبُ بْنُ الْحَسَنِ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ لَهُ وَلِابْنِهِ ‏ ‏عَلِيٍّ ‏ ‏انْطَلِقَا إِلَى ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏فَاسْمَعَا مِنْ حَدِيثِهِ قَالَ فَانْطَلَقْنَا فَإِذَا هُوَ فِي ‏ ‏حَائِطٍ ‏ ‏لَهُ فَلَمَّا ‏ ‏رَآنَا أَخَذَ رِدَاءَهُ فَجَاءَنَا فَقَعَدَ فَأَنْشَأَ يُحَدِّثُنَا حَتَّى أَتَى عَلَى ذِكْرِ بِنَاءِ الْمَسْجِدِ قَالَ كُنَّا نَحْمِلُ ‏ ‏لَبِنَةً ‏ ‏لَبِنَةً ‏ ‏وَعَمَّارُ بْنُ يَاسرٍ ‏ ‏يَحْمِلُ ‏ ‏لَبِنَتَيْنِ ‏ ‏لَبِنَتَيْنِ ‏ ‏قَالَ فَرَآهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَعَلَ يَنْفُضُ التُّرَابَ عَنْهُ وَيَقُولُ يَا ‏ ‏عَمَّارُ ‏ ‏أَلَا تَحْمِلُ ‏ ‏لَبِنَةً ‏ ‏كَمَا يَحْمِلُ أَصْحَابُكَ قَالَ إِنِّي أُرِيدُ الْأَجْرَ مِنْ اللَّهِ قَالَ فَجَعَلَ يَنْفُضُ التُّرَابَ عَنْهُ وَيَقُولُ وَيْحَ ‏ ‏عَمَّارٍ ‏ ‏تَقْتُلُهُ ‏ ‏الْفِئَةُ ‏ ‏الْبَاغِيَةُ ‏ ‏يَدْعُوهُمْ إِلَى الْجَنَّةِ وَيَدْعُونَهُ إِلَى النَّارِ قَالَ فَجَعَلَ ‏ ‏عَمَّارٌ ‏ ‏يَقُولُ أَعُوذُ بِالرَّحْمَنِ مِنْ الْفِتَنِ ‏","","",""],[11430,11430,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي عُتْبَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشَدَّ حَيَاءً مِنْ الْعَذْرَاءِ فِي ‏ ‏خِدْرِهَا ‏ ‏وَكَانَ إِذَا كَرِهَ الشَّيْءَ عَرَفْنَاهُ فِي وَجْهِهِ ‏","","",""],[11431,11431,"","","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏أُنَيْسُ بْنُ أَبِي يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ وَهُوَ عَاصِبٌ رَأْسَهُ قَالَ فَاتَّبَعْتُهُ حَتَّى صَعِدَ عَلَى الْمِنْبَرِ قَالَ فَقَالَ ‏ ‏إِنِّي السَّاعَةَ لَقَائِمٌ عَلَى الْحَوْضِ قَالَ ثُمَّ قَالَ إِنَّ عَبْدًا عُرِضَتْ عَلَيْهِ الدُّنْيَا وَزِينَتَهَا فَاخْتَارَ الْآخِرَةَ فَلَمْ ‏ ‏يَفْطَنْ ‏ ‏لَهَا أَحَدٌ مِنْ الْقَوْمِ إِلَّا ‏ ‏أَبُو بَكْرٍ ‏ ‏فَقَالَ بِأَبِي أَنْتَ وَأُمِّي بَلْ ‏ ‏نَفْدِيكَ بِأَمْوَالِنَا وَأَنْفُسِنَا وَأَوْلَادِنَا قَالَ ثُمَّ هَبَطَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْمِنْبَرِ فَمَا رُئِيَ عَلَيْهِ حَتَّى السَّاعَةِ ‏","","",""],[11432,11432,"","","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏حَدَّثَنَا ‏ ‏أُنَيْسُ بْنُ أَبِي يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏بَنِي عَمْرِو بْنِ عَوْفٍ ‏ ‏وَرَجُلًا مِنْ ‏ ‏بَنِي خُدْرَةَ ‏ ‏امْتَرَيَا ‏ ‏فِي الْمَسْجِدِ الَّذِي أُسِّسَ عَلَى التَّقْوَى فَقَالَ ‏ ‏الْعَوْفِيُّ ‏ ‏هُوَ ‏ ‏مَسْجِدُ قُبَاءٍ ‏ ‏وَقَالَ ‏ ‏الْخُدْرِيُّ ‏ ‏هُوَ ‏ ‏مَسْجِدُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَيَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَاهُ عَنْ ذَلِكَ فَقَالَ هُوَ ‏ ‏مَسْجِدِي ‏ ‏هَذَا وَفِي ذَلِكَ خَيْرٌ كَثِيرٌ ‏","","",""],[11433,11433,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏الدَّسْتُوَائِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏جَلَسَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ وَجَلَسْنَا حَوْلَهُ فَقَالَ ‏ ‏إِنَّمَا ‏ ‏أَخَافُ عَلَيْكُمْ بَعْدِي مَا يُفْتَحُ عَلَيْكُمْ مِنْ زَهْرَةِ الدُّنْيَا وَزِينَتِهَا فَقَالَ رَجُلٌ ‏ ‏أَوَيَأْتِي الْخَيْرُ بِالشَّرِّ يَا رَسُولَ اللَّهِ فَسَكَتَ عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقِيلَ لَهُ مَا شَأْنُكَ تُكَلِّمُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا يُكَلِّمُكَ قَالَ وَأُرِنَا أَنَّهُ يُنْزَلُ عَلَيْهِ قَالَ فَأَفَاقَ يَمْسَحُ عَنْهُ ‏ ‏الرُّحَضَاءَ ‏ ‏وَقَالَ أَيْنَ هَذَا السَّائِلُ وَكَأَنَّهُ حَمِدَهُ فَقَالَ إِنَّهُ ‏ ‏لَا يَأْتِي الْخَيْرُ بِالشَّرِّ إِنَّ مِمَّا يُنْبِتُ الرَّبِيعُ يَقْتُلُ أَوْ ‏ ‏يُلِمُّ ‏ ‏إِلَّا آكِلَةَ الْخَضِرِ فَإِنَّهَا أَكَلَتْ حَتَّى إِذَا ‏ ‏امْتَلَأَتْ خَاصِرَتَاهَا ‏ ‏اسْتَقْبَلَتْ عَيْنَ الشَّمْسِ ‏ ‏فَثَلَطَتْ ‏ ‏وَبَالَتْ ثُمَّ ‏ ‏رَتَعَتْ ‏ ‏وَإِنَّ هَذَا الْمَالَ خَضِرَةٌ حُلْوَةً وَنِعْمَ صَاحِبُ الْمُسْلِمِ هُوَ لِمَنْ أَعْطَى مِنْهُ الْيَتِيمَ وَالْمِسْكِينَ وَابْنَ السَّبِيلِ ‏ ‏أَوْ كَمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّ الَّذِي يَأْخُذُهُ بِغَيْرِ حَقِّهِ كَالَّذِي يَأْكُلُ وَلَا يَشْبَعُ فَيَكُونُ عَلَيْهِ شَهِيدًا يَوْمَ الْقِيَامَةِ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ عَلَى الْمِنْبَرِ ذَاتَ يَوْمٍ فَقَالَ ‏ ‏إِنَّ مِمَّا أَخْشَى عَلَيْكُمْ فَذَكَرَ الْحَدِيثَ وَقَالَ يَقْتُلُ حَبَطًا أَوْ ‏ ‏يُلِمُّ ‏","","",""],[11434,11434,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ الْمُبَارَكِ ‏ ‏وَرَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏الْمَهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ بَعْثًا إِلَى ‏ ‏بَنِي لَحْيَانَ ‏ ‏مِنْ ‏ ‏بَنِي هُذَيْلٍ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏مِنْ ‏ ‏هُذَيْلٍ ‏ ‏قَالَ لِيَنْبَعِثْ مِنْ كُلِّ رَجُلَيْنِ أَحَدُهُمَا وَالْأَجْرُ بَيْنَهُمَا ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ بَارِكْ لَنَا فِي ‏ ‏مُدِّنَا ‏ ‏وَصَاعِنَا ‏ ‏وَاجْعَلْ مَعَ الْبَرَكَةِ بَرَكَتَيْنِ ‏","","",""],[11435,11435,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا يَحْقِرَنَّ أَحَدُكُمْ نَفْسَهُ إِذَا رَأَى أَمْرَ اللَّهِ عَلَيْهِ فِيهِ مَقَالًا فَلَا يَقُولُ بِهِ ‏ ‏فَيَلْقَى اللَّهَ وَقَدْ أَضَاعَ ذَلِكَ فَيَقُولُ ‏ ‏مَا مَنَعَكَ فَيَقُولُ خَشِيتُ النَّاسَ فَيَقُولُ أَنَا ‏ ‏كُنْتُ أَحَقَّ أَنْ ‏ ‏تَخْشَى ‏","","",""],[11436,11436,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَمْنَعَنَّ أَحَدَكُمْ مَخَافَةُ النَّاسِ أَنْ يَتَكَلَّمَ بِحَقٍّ إِذَا عَلِمَهُ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏فَمَا زَالَ بِنَا الْبَلَاءُ حَتَّى قَصَّرْنَا وَإِنَّا لَنَبْلُغُ فِي الشَّرِّ ‏ ‏و قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا نَضْرَةَ ‏","","",""],[11437,11437,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ثَمَانِ عَشَرَ مَضَتْ مِنْ رَمَضَانَ ‏ ‏فَصَامَ صَائِمُونَ وَأَفْطَرَ مُفْطِرُونَ فَلَمْ يَعِبْ هَؤُلَاءِ عَلَى هَؤُلَاءِ وَلَا هَؤُلَاءِ عَلَى هَؤُلَاءِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي بِهَذَا الْحَدِيثِ أَرْبَعَةٌ أَحَدُهُمْ ‏ ‏قَتَادَةُ ‏ ‏وَهَذَا حَدِيثُ ‏ ‏قَتَادَةَ ‏","","",""],[11438,11438,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ أَخِي انْطَلَقَ بَطْنُهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْقِهِ عَسَلًا فَسَقَاهُ فَقَالَ إِنِّي سَقَيْتُهُ فَلَمْ يَزِدْهُ إِلَّا ‏ ‏اسْتِطْلَاقًا ‏ ‏فَقَالَ لَهُ ثَلَاثَ مَرَّاتٍ ثُمَّ جَاءَهُ الرَّابِعَةَ فَقَالَ اسْقِهِ عَسَلًا فَقَالَ قَدْ سَقَيْتُهُ فَلَمْ يَزِدْهُ إِلَّا ‏ ‏اسْتِطْلَاقًا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ اللَّهُ وَكَذَبَ بَطْنُ أَخِيكَ فَسَقَاهُ ‏ ‏فَبَرِئَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[11439,11439,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏أَوْ ‏ ‏أَبِي سُلَيْمَانَ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏وَقَالَ ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَيَكُونُ أُمَرَاءُ ‏ ‏يَغْشَاهُمْ ‏ ‏غَوَاشٍ ‏ ‏أَوْ ‏ ‏حَوَاشٍ ‏ ‏مِنْ النَّاسِ يَظْلِمُونَ وَيَكْذِبُونَ فَمَنْ أَعَانَهُمْ عَلَى ظُلْمِهِمْ وَصَدَّقَهُمْ بِكَذِبِهِمْ فَلَيْسَ مِنِّي وَلَا أَنَا مِنْهُ وَمَنْ لَمْ يُصَدِّقْهُمْ بِكَذِبِهِمْ وَلَمْ يُعِنْهُمْ عَلَى ظُلْمِهِمْ فَأَنَا مِنْهُ وَهُوَ مِنِّي ‏","","",""],[11440,11440,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي عُتْبَةَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏ابْنُ عُتْبَةَ ‏ ‏مَوْلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشَدَّ حَيَاءً مِنْ عَذْرَاءَ فِي ‏ ‏خِدْرِهَا ‏ ‏وَكَانَ إِذَا كَرِهَ شَيْئًا عَرَفْنَاهُ فِي وَجْهِهِ ‏","","",""],[11441,11441,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الْأَغَرِّ أَبِي مُسْلِمٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَشْهَدُ عَلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏أَنَّهُمَا ‏ ‏شَهِدَا عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَقْعُدُ قَوْمٌ يَذْكُرُونَ اللَّهَ إِلَّا ‏ ‏حَفَّتْهُمْ ‏ ‏الْمَلَائِكَةُ وَغَشِيَتْهُمْ الرَّحْمَةُ وَنَزَلَتْ عَلَيْهِمْ ‏ ‏السَّكِينَةُ ‏ ‏وَذَكَرَهُمْ اللَّهُ فِيمَنْ عِنْدَهُ ‏","","",""],[11442,11442,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏مَرْوَانَ ‏ ‏خَطَبَ قَبْلَ الصَّلَاةِ فَقَالَ لَهُ رَجُلٌ الصَّلَاةُ قَبْلَ الْخُطْبَةِ فَقَالَ لَهُ ‏ ‏مَرْوَانُ ‏ ‏تُرِكَ ذَاكَ يَا أَبَا فُلَانٍ فَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَمَّا هَذَا فَقَدْ قَضَى مَا عَلَيْهِ قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُنْكِرْهُ بِيَدِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ وَذَاكَ أَضْعَفُ الْإِيمَانِ ‏","","",""],[11443,11443,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو نَعَامَةَ السَّعْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ فَلَمَّا كَانَ فِي بَعْضِ صَلَاتِهِ خَلَعَ نَعْلَيْهِ فَوَضَعَهُمَا عَنْ يَسَارِهِ فَلَمَّا رَأَى النَّاسُ ذَلِكَ خَلَعُوا نِعَالَهُمْ فَلَمَّا قَضَى صَلَاتَهُ قَالَ مَا بَالُكُمْ أَلْقَيْتُمْ نِعَالَكُمْ قَالُوا رَأَيْنَاكَ أَلْقَيْتَ نَعْلَيْكَ فَأَلْقَيْنَا نِعَالَنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏جِبْرِيلَ ‏ ‏أَتَانِي فَأَخْبَرَنِي أَنَّ فِيهِمَا قَذَرًا ‏ ‏أَوْ قَالَ أَذًى ‏ ‏فَأَلْقَيْتُهُمَا فَإِذَا جَاءَ أَحَدُكُمْ إِلَى الْمَسْجِدِ فَلْيَنْظُرْ فِي نَعْلَيْهِ فَإِنْ رَأَى فِيهِمَا قَذَرًا ‏ ‏أَوْ قَالَ أَذًى ‏ ‏فَلْيَمْسَحْهُمَا وَلْيُصَلِّ فِيهِمَا ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏لَمْ يَجِئْ فِي هَذَا الْحَدِيثِ بَيَانُ مَا كَانَ فِي النَّعْلِ ‏","","",""],[11444,11444,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْعَزْلِ ‏ ‏فَقَالَ ‏ ‏إِنْ تَفْعَلُوا ذَلِكَ لَا عَلَيْكُمْ أَنْ لَا تَفْعَلُوهُ فَإِنَّهُ لَيْسَ ‏ ‏نَسَمَةٌ ‏ ‏قَضَى اللَّهُ أَنْ تَكُونَ إِلَّا هِيَ ‏ ‏كَائِنَةٌ ‏","","",""],[11445,11445,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ ‏ ‏أَخْبَرَهُ ‏ ‏وَأَبُو هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى فِي جِدَارِ الْمَسْجِدِ ‏ ‏نُخَامَةً ‏ ‏فَتَنَاوَلَ حَصَاةً ‏ ‏فَحَتَّهَا ‏ ‏ثُمَّ قَالَ ‏ ‏إِذَا ‏ ‏تَنَخَّمَ ‏ ‏أَحَدُكُمْ فَلَا ‏ ‏يَتَنَخَّمَنَّ ‏ ‏قِبَلَ وَجْهِهِ وَلَا عَنْ يَمِينِهِ وَلْيَبْصُقْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ الْيُسْرَى ‏","","",""],[11446,11446,"","","‏ ‏حَدَّثَنَا ‏ ‏سَكَنُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏حُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏وَأَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولَانِ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نُخَامَةً ‏ ‏فِي الْقِبْلَةِ فَتَنَاوَلَ حَصَاةً فَحَكَّهَا بِهَا ثُمَّ قَالَ ‏ ‏لَا ‏ ‏يَتَنَخَّمْ ‏ ‏أَحَدٌ فِي الْقِبْلَةِ وَلَا عَنْ يَمِينِهِ وَلْيَبْصُقْ عَنْ يَسَارِهِ أَوْ تَحْتَ رِجْلِهِ الْيُسْرَى ‏","","",""],[11447,11447,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ شُجَاعٍ ‏ ‏حَدَّثَنِي ‏ ‏خُصَيْفٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّتَيْنِ عَلَى الْمِنْبَرِ يَقُولُ ‏ ‏الذَّهَبُ بِالذَّهَبِ وَالْفِضَّةُ بِالْفِضَّةِ وَزْنًا بِوَزْنٍ ‏","","",""],[11448,11448,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏سَالِمٌ يَعْنِي ابْنَ أَبِي حَفْصَةَ ‏ ‏وَالْأَعْمَشُ ‏ ‏وَعَبْدُ اللَّهِ بْنُ صُهْبَانَ ‏ ‏وَكَثِيرٌ النَّوَّاءُ ‏ ‏وَابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَهْلَ الدَّرَجَاتِ الْعُلَى ‏ ‏لَيَرَاهُمْ مَنْ تَحْتَهُمْ كَمَا تَرَوْنَ النَّجْمَ الطَّالِعَ فِي أُفُقٍ مِنْ آفَاقِ السَّمَاءِ أَلَا وَإِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏مِنْهُمْ وَأَنْعَمَا ‏","","",""],[11449,11449,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏شَهْرٍ ‏ ‏قَالَ ‏ ‏لَقِينَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏وَنَحْنُ نُرِيدُ ‏ ‏الطُّورَ ‏ ‏فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تُشَدُّ ‏ ‏الْمَطِيُّ ‏ ‏إِلَّا إِلَى ثَلَاثَةِ مَسَاجِدَ ‏ ‏الْمَسْجِدِ الْحَرَامِ ‏ ‏وَمَسْجِدِ الْمَدِينَةِ ‏ ‏وَبَيْتِ الْمَقْدِسِ ‏","","",""],[11450,11450,"","","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْعَزْلِ ‏ ‏فَقَالَ ‏ ‏لَيْسَ مِنْ كُلِّ ‏ ‏الْمَاءِ ‏ ‏يَكُونُ الْوَلَدُ إِذَا أَرَادَ اللَّهُ أَنْ يَخْلُقَ شَيْئًا لَمْ يَمْنَعْهُ شَيْءٌ ‏","","",""],[11451,11451,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏وَهَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُبْغِضُ ‏ ‏الْأَنْصَارَ ‏ ‏رَجُلٌ يُؤْمِنُ بِاللَّهِ وَرَسُولِهِ ‏ ‏وَقَالَ ‏ ‏هَاشِمٌ ‏ ‏يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ‏","","",""],[11452,11452,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَاتَلَ أَحَدُكُمْ أَخَاهُ فَلْيَجْتَنِبْ الْوَجْهَ ‏","","",""],[11453,11453,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏لَا نَتْرُكَ أَحَدًا يَمُرُّ بَيْنَ أَيْدِينَا فَإِنْ أَبَى إِلَّا أَنْ نَدْفَعَهُ ‏ ‏أَوْ نَحْوَ هَذَا ‏","","",""],[11454,11454,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏وَعَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏اخْتِنَاثِ ‏ ‏الْأَسْقِيَةِ ‏","","",""],[11455,11455,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَثَاءَبَ أَحَدُكُمْ فَلْيَضَعْ يَدَهُ عَلَى ‏ ‏فِيهِ فَإِنَّ الشَّيْطَانَ يَدْخُلُ مَعَ التَّثَاؤُبِ ‏","","",""],[11456,11456,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنِي ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏جَاءَ نَاسٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَسَأَلُوهُ فَأَعْطَاهُمْ قَالَ فَجَعَلَ لَا يَسْأَلُهُ أَحَدٌ مِنْهُمْ إِلَّا أَعْطَاهُ حَتَّى نَفِدَ مَا عِنْدَهُ فَقَالَ لَهُمْ حِينَ أَنْفَقَ كُلَّ شَيْءٍ بِيَدِهِ ‏ ‏وَمَا يَكُونُ عِنْدَنَا مِنْ خَيْرٍ فَلَنْ نَدَّخِرَهُ عَنْكُمْ وَإِنَّهُ مَنْ يَسْتَعْفِفْ يُعِفَّهُ اللَّهُ وَمَنْ يَسْتَغْنِ يُغْنِهِ اللَّهُ وَمَنْ يَتَصَبَّرْ يُصَبِّرْهُ اللَّهُ وَلَنْ تُعْطَوْا عَطَاءً خَيْرًا أَوْسَعَ مِنْ الصَّبْرِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَالِكَ بْنَ أَنَسٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏فَذَكَرَ مِثْلَ مَعْنَاهُ ‏","","",""],[11457,11457,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ أَبِي مُسْلِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا اجْتَمَعَ قَوْمٌ يَذْكُرُونَ اللَّهَ إِلَّا حَفَّتْهُمْ الْمَلَائِكَةُ وَتَغَشَّتْهُمْ الرَّحْمَةُ وَنَزَلَتْ عَلَيْهِمْ السَّكِينَةُ وَذَكَرَهُمْ اللَّهُ فِيمَنْ عِنْدَهُ وَقَالَ إِنَّ اللَّهَ يُمْهِلُ حَتَّى إِذَا كَانَ ثُلُثُ اللَّيْلِ الْآخِرُ نَزَلَ اللَّهُ عَزَّ وَجَلَّ إِلَى هَذِهِ السَّمَاءِ فَنَادَى هَلْ مِنْ مُذْنِبٍ يَتُوبُ هَلْ مِنْ مُسْتَغْفِرٍ هَلْ مِنْ دَاعٍ هَلْ مِنْ سَائِلٍ إِلَى الْفَجْرِ ‏","","",""],[11458,11458,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏وَضَعَ رَجُلٌ يَدَهُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ وَاللَّهِ مَا أُطِيقُ أَنْ أَضَعَ يَدِي عَلَيْكَ مِنْ شِدَّةِ حُمَّاكَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّا مَعْشَرَ الْأَنْبِيَاءِ ‏ ‏يُضَاعَفُ لَنَا ‏ ‏الْبَلَاءُ ‏ ‏كَمَا يُضَاعَفُ لَنَا الْأَجْرُ إِنْ كَانَ النَّبِيُّ مِنْ الْأَنْبِيَاءِ ‏ ‏يُبْتَلَى ‏ ‏بِالْقُمَّلِ حَتَّى يَقْتُلَهُ وَإِنْ كَانَ النَّبِيُّ مِنْ الْأَنْبِيَاءِ ‏ ‏لَيُبْتَلَى ‏ ‏بِالْفَقْرِ حَتَّى يَأْخُذَ الْعَبَاءَةَ ‏ ‏فَيَخُونَهَا ‏ ‏وَإِنْ كَانُوا لَيَفْرَحُونَ ‏ ‏بِالْبَلَاءِ ‏ ‏كَمَا تَفْرَحُونَ بِالرَّخَاءِ ‏","","",""],[11459,11459,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا عَجِلَ أَحَدُكُمْ أَوْ ‏ ‏أَقْحَطَ ‏ ‏فَلَا يَغْتَسِلَنَّ ‏","","",""],[11460,11460,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ ‏ ‏رَأَى الطِّينَ فِي أَنْفِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَرْنَبَتِهِ ‏ ‏مِنْ أَثَرِ السُّجُودِ وَكَانُوا مُطِرُوا مِنْ اللَّيْلِ ‏","","",""],[11461,11461,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏اعْتَكَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ فَسَمِعَهُمْ يَجْهَرُوا بِالْقِرَاءَةِ وَهُوَ فِي قُبَّةٍ لَهُ فَكَشَفَ السُّتُورَ ‏ ‏وَكَشَفَ ‏ ‏وَقَالَ ‏ ‏أَلَا كُلُّكُمْ ‏ ‏مُنَاجٍ رَبَّهُ فَلَا يُؤْذِيَنَّ بَعْضُكُمْ بَعْضًا وَلَا يَرْفَعَنَّ بَعْضُكُمْ عَلَى ‏ ‏بَعْضٍ فِي الْقِرَاءَةِ ‏ ‏أَوْ قَالَ فِي الصَّلَاةِ ‏","","",""],[11462,11462,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَتَتَّبِعُنَّ سُنَنَ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏شِبْرًا بِشِبْرٍ وَذِرَاعًا بِذِرَاعٍ حَتَّى لَوْ دَخَلَ رَجُلٌ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏جُحْرَ ضَبٍّ لَتَبِعْتُمُوهُمْ فِيهِ ‏ ‏وَقَالَ مَرَّةً لَتَبِعْتُمُوهُ فِيهِ ‏","","",""],[11463,11463,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَلَصَ الْمُؤْمِنُونَ مِنْ النَّارِ يَوْمَ الْقِيَامَةِ وَأَمِنُوا فَمَا مُجَادَلَةُ أَحَدِكُمْ لِصَاحِبِهِ فِي الْحَقِّ يَكُونُ لَهُ فِي الدُّنْيَا بِأَشَدَّ مُجَادَلَةً لَهُ مِنْ الْمُؤْمِنِينَ لِرَبِّهِمْ فِي إِخْوَانِهِمْ الَّذِينَ أُدْخِلُوا النَّارَ قَالَ يَقُولُونَ رَبَّنَا إِخْوَانُنَا كَانُوا يُصَلُّونَ مَعَنَا وَيَصُومُونَ مَعَنَا وَيَحُجُّونَ مَعَنَا فَأَدْخَلْتَهُمْ النَّارَ قَالَ فَيَقُولُ ‏ ‏اذْهَبُوا فَأَخْرِجُوا مَنْ عَرَفْتُمْ فَيَأْتُونَهُمْ فَيَعْرِفُونَهُمْ بِصُوَرِهِمْ لَا تَأْكُلُ النَّارُ صُوَرَهُمْ فَمِنْهُمْ مَنْ أَخَذَتْهُ النَّارُ إِلَى أَنْصَافِ سَاقَيْهِ وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى كَعْبَيْهِ فَيُخْرِجُونَهُمْ فَيَقُولُونَ رَبَّنَا أَخْرَجْنَا مَنْ أَمَرْتَنَا ثُمَّ يَقُولُ أَخْرِجُوا مَنْ كَانَ فِي قَلْبِهِ وَزْنُ دِينَارٍ مِنْ الْإِيمَانِ ثُمَّ مَنْ كَانَ فِي قَلْبِهِ وَزْنُ نِصْفِ دِينَارٍ حَتَّى يَقُولَ مَنْ كَانَ فِي قَلْبِهِ ‏ ‏مِثْقَالُ ‏ ‏ذَرَّةٍ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَمَنْ لَمْ يُصَدِّقْ بِهَذَا فَلْيَقْرَأْ هَذِهِ الْآيَةَ ‏ { ‏إِنَّ اللَّهَ لَا يَظْلِمُ ‏ ‏مِثْقَالَ ‏ ‏ذَرَّةٍ وَإِنْ تَكُ حَسَنَةً يُضَاعِفْهَا وَيُؤْتِ مِنْ لَدُنْهُ أَجْرًا عَظِيمًا ‏} ‏قَالَ فَيَقُولُونَ رَبَّنَا قَدْ أَخْرَجْنَا مَنْ أَمَرْتَنَا فَلَمْ يَبْقَ فِي النَّارِ أَحَدٌ فِيهِ خَيْرٌ قَالَ ثُمَّ يَقُولُ اللَّهُ شَفَعَتْ الْمَلَائِكَةُ وَشَفَعَ الْأَنْبِيَاءُ وَشَفَعَ الْمُؤْمِنُونَ وَبَقِيَ أَرْحَمُ الرَّاحِمِينَ قَالَ فَيَقْبِضُ قَبْضَةً مِنْ النَّارِ ‏ ‏أَوْ قَالَ قَبْضَتَيْنِ ‏ ‏نَاسٌ لَمْ يَعْمَلُوا لِلَّهِ خَيْرًا قَطُّ قَدْ احْتَرَقُوا حَتَّى صَارُوا حُمَمًا قَالَ فَيُؤْتَى بِهِمْ إِلَى مَاءٍ يُقَالُ لَهُ مَاءُ الْحَيَاةِ فَيُصَبُّ عَلَيْهِمْ فَيَنْبُتُونَ كَمَا تَنْبُتُ الْحِبَّةُ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ فَيَخْرُجُونَ مِنْ ‏ ‏أَجْسَادِهِمْ مِثْلَ اللُّؤْلُؤِ فِي أَعْنَاقِهِمْ الْخَاتَمُ عُتَقَاءُ اللَّهِ قَالَ فَيُقَالُ لَهُمْ ادْخُلُوا الْجَنَّةَ فَمَا تَمَنَّيْتُمْ ‏ ‏أَوْ رَأَيْتُمْ ‏ ‏مِنْ شَيْءٍ فَهُوَ لَكُمْ عِنْدِي أَفْضَلُ مِنْ هَذَا قَالَ فَيَقُولُونَ رَبَّنَا وَمَا أَفْضَلُ مِنْ ذَلِكَ قَالَ فَيَقُولُ رِضَائِي عَلَيْكُمْ فَلَا أَسْخَطُ عَلَيْكُمْ أَبَدًا ‏","","",""],[11464,11464,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْمُلَامَسَةِ ‏ ‏وَالْمُلَامَسَةُ يُمَسُّ الثَّوْبُ لَا يُنْظَرُ إِلَيْهِ ‏ ‏وَعَنْ الْمُنَابَذَةِ ‏ ‏وَهُوَ طَرْحُ الثَّوْبِ الرَّجُلُ بِالْبَيْعِ قَبْلَ أَنْ يُقَلِّبَهُ وَيَنْظُرَ إِلَيْهِ ‏","","",""],[11465,11465,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ الْجُنْدَعِيِّ ‏ ‏سَمِعَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا صَلَاةَ بَعْدَ صَلَاةِ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ ‏ ‏وَقَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏حَتَّى تَرْتَفِعَ الشَّمْسُ ‏ ‏وَلَا صَلَاةَ بَعْدَ صَلَاةِ الْعَصْرِ حَتَّى تَغِيبَ الشَّمْسُ ‏","","",""],[11466,11466,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ أَبِي عَطَاءِ بْنِ أَبِي الْخُوَارِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عِيَاضٍ ‏ ‏وَعَطَاءِ بْنِ بُخْتٍ ‏ ‏كِلَاهُمَا يُخْبِرُ ‏ ‏عُمَرَ بْنَ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُمَا سَمِعَاهُ يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏يَقُولُ ‏ ‏لَا صَلَاةَ بَعْدَ صَلَاةِ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ وَلَا صَلَاةَ بَعْدَ صَلَاةِ الْعَصْرِ حَتَّى اللَّيْلِ ‏","","",""],[11467,11467,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ ثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏وَحَدَّثَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْمُلَامَسَةِ ‏ ‏وَالْمُلَامَسَةُ لَمْسُ الثَّوْبِ لَا يُنْظَرُ إِلَيْهِ وَعَنْ ‏ ‏الْمُنَابَذَةِ ‏ ‏وَالْمُنَابَذَةُ طَرْحُ الرَّجُلِ ثَوْبَهُ إِلَى الرَّجُلِ قَبْلَ أَنْ يُقَلِّبَهُ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏عَطَاءُ بْنُ يَزِيدَ الْجُنْدَعِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏ ‏يَعْنِي مِثْلَ حَدِيثِ ‏ ‏عَبْدِ الرَّزَّاقِ ‏ ‏وَابْنِ بَكْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏وَقَالَ حَتَّى تَرْتَفِعَ الشَّمْسُ ‏","","",""],[11468,11468,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ ثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لِبْسَتَيْنِ وَعَنْ بَيْعَتَيْنِ أَمَّا اللِّبْسَتَانِ فَاشْتِمَالُ ‏ ‏الصَّمَّاءِ ‏ ‏أَنْ يَشْتَمِلَ فِي ثَوْبٍ وَاحِدٍ يَضَعَ طَرَفَيْ الثَّوْبِ عَلَى عَاتِقِهِ الْأَيْسَرِ وَيَتَّزِرَ بِشِقِّهِ الْأَيْمَنِ وَالْأُخْرَى أَنْ يَحْتَبِيَ فِي ثَوْبٍ وَاحِدٍ لَيْسَ عَلَيْهِ غَيْرُهُ وَيُفْضِيَ بِفَرْجِهِ إِلَى السَّمَاءِ وَأَمَّا الْبَيْعَتَانِ فَالْمُنَابَذَةُ وَالْمُلَامَسَةُ ‏ ‏وَالْمُنَابَذَةُ أَنْ يَقُولَ إِذَا نَبَذْتَ هَذَا الثَّوْبَ فَقَدْ وَجَبَ الْبَيْعُ ‏ ‏وَالْمُلَامَسَةُ أَنْ يَمَسَّهُ بِيَدِهِ وَلَا يَلْبَسَهُ وَلَا يُقَلِّبَهُ إِذَا مَسَّهُ وَجَبَ الْبَيْعُ ‏","","",""],[11469,11469,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَقَالَ قَالَ ‏ ‏الثَّوْرِيُّ ‏ ‏فَحَدَّثَنِي ‏ ‏أَبُو إِسْحَاقَ ‏ ‏أَنَّ ‏ ‏الْأَغَرَّ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ يُنَادِي مُنَادٍ ‏ ‏أَنَّ لَكُمْ أَنْ تَحْيَوْا فَلَا تَمُوتُوا أَبَدًا وَأَنَّ لَكُمْ أَنْ تَصِحُّوا فَلَا ‏ ‏تَسْقَمُوا ‏ ‏أَبَدًا وَأَنَّ لَكُمْ أَنْ تَشِبُّوا وَلَا ‏ ‏تَهْرَمُوا ‏ ‏وَأَنَّ لَكُمْ أَنْ تَنْعَمُوا وَلَا تَبْأَسُوا أَبَدًا فَذَلِكَ قَوْلُهُ عَزَّ وَجَلَّ ‏ { ‏وَنُودُوا أَنْ تِلْكُمْ الْجَنَّةُ أُورِثْتُمُوهَا بِمَا كُنْتُمْ تَعْمَلُونَ ‏}","","",""],[11470,11470,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَقْتَتِلَ فِئَتَانِ عَظِيمَتَانِ دَعْوَاهُمَا وَاحِدَةٌ ‏ ‏تَمْرُقُ ‏ ‏بَيْنَهُمَا ‏ ‏مَارِقَةٌ ‏ ‏يَقْتُلُهَا أَوْلَاهُمَا بِالْحَقِّ ‏","","",""],[11471,11471,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَزَالُ الْعَبْدُ فِي صَلَاةٍ مَا كَانَ فِي مُصَلَّاهُ يَنْتَظِرُ الصَّلَاةَ تَقُولُ الْمَلَائِكَةُ اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ حَتَّى يَنْصَرِفَ أَوْ ‏ ‏يُحْدِثَ ‏ ‏فَقُلْتُ مَا ‏ ‏يُحْدِثُ ‏ ‏فَقَالَ كَذَا قُلْتُ ‏ ‏لِأَبِي سَعِيدٍ ‏ ‏فَقَالَ ‏ ‏يَفْسُو أَوْ يَضْرِطُ ‏","","",""],[11472,11472,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الصَّهْبَاءِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏لَا أَعْلَمُهُ إِلَّا رَفَعَهُ ‏ ‏قَالَ ‏ ‏إِذَا أَصْبَحَ ابْنُ ‏ ‏آدَمَ ‏ ‏فَإِنَّ أَعْضَاءَهُ تُكَفِّرُ لِلِّسَانِ تَقُولُ اتَّقِ اللَّهَ فِينَا فَإِنَّكَ إِنْ اسْتَقَمْتَ اسْتَقَمْنَا وَأَنْ ‏ ‏اعْوَجَجْتَ ‏ ‏اعْوَجَجْنَا ‏","","",""],[11473,11473,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَنْتَ تَخْلُقُهُ أَنْتَ تَرْزُقُهُ فَأَقْرِرْهُ مَقَرَّهُ فَإِنَّمَا كَانَ قَدَرٌ ‏","","",""],[11474,11474,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صِيَامِ يَوْمَيْنِ يَوْمِ الْفِطْرِ وَيَوْمِ الْأَضْحَى وَعَنْ لِبْسَتَيْنِ ‏ ‏الصَّمَّاءِ ‏ ‏وَأَنْ ‏ ‏يَحْتَبِيَ ‏ ‏الرَّجُلُ فِي الثَّوْبِ الْوَاحِدِ وَعَنْ صَلَاةٍ فِي سَاعَتَيْنِ بَعْدَ الصُّبْحِ وَبَعْدَ الْعَصْرِ ‏","","",""],[11475,11475,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَحَسَنٌ ‏ ‏قَالَا ثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏بِشْرِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْعُو ‏ ‏بِعَرَفَةَ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏وَيَرْفَعُ يَدَيْهِ هَكَذَا يَجْعَلُ ظَاهِرَهُمَا فَوْقَ وَبَاطِنَهُمَا أَسْفَلَ ‏ ‏وَوَصَفَ ‏ ‏حَمَّادٌ ‏ ‏وَرَفَعَ ‏ ‏حَمَّادٌ ‏ ‏يَدَيْهِ وَكَفَّيْهِ مِمَّا ‏ ‏يَلِي ‏ ‏الْأَرْضَ ‏","","",""],[11476,11476,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الشَّيْطَانَ يَأْتِي أَحَدَكُمْ وَهُوَ فِي صَلَاتِهِ فَيَأْخُذُ شَعْرَةً مِنْ ‏ ‏دُبُرِهِ ‏ ‏فَيَمُدُّهَا فَيَرَى أَنَّهُ قَدْ ‏ ‏أَحْدَثَ ‏ ‏فَلَا يَنْصَرِفَنَّ حَتَّى يَسْمَعَ صَوْتًا أَوْ يَجِدَ رِيحًا ‏","","",""],[11477,11477,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الشَّيْطَانَ يَأْتِي أَحَدَكُمْ وَهُوَ فِي صَلَاتِهِ فَيَأْخُذُ ‏ ‏بِشَعْرَةٍ ‏ ‏مِنْ ‏ ‏دُبُرِهِ ‏ ‏فَيَمُدُّهَا فَيَرَى أَنَّهُ قَدْ ‏ ‏أَحْدَثَ ‏ ‏فَلَا يَنْصَرِفْ حَتَّى يَسْمَعَ صَوْتًا أَوْ يَجِدَ رِيحًا ‏","","",""],[11478,11478,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَبْعَثَنَّ اللَّهُ عَزَّ وَجَلَّ فِي هَذِهِ الْأُمَّةِ خَلِيفَةً ‏ ‏يَحْثِي ‏ ‏الْمَالَ ‏ ‏حَثْيًا ‏ ‏وَلَا يَعُدُّهُ عَدًّا ‏","","",""],[11479,11479,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏الْمُعَلَّى بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْعَلَاءُ ‏ ‏رَجُلٌ مِنْ ‏ ‏بَنِي مُزَيْنَةَ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُمْ ‏ ‏كَانُوا جُلُوسًا يَقْرَءُونَ الْقُرْآنَ وَيَدْعُونَ قَالَ فَخَرَجَ عَلَيْهِمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَلَمَّا رَأَيْنَاهُ سَكَتْنَا فَقَالَ أَلَيْسَ كُنْتُمْ تَصْنَعُونَ كَذَا وَكَذَا قُلْنَا نَعَمْ قَالَ فَاصْنَعُوا كَمَا كُنْتُمْ تَصْنَعُونَ وَجَلَسَ مَعَنَا ثُمَّ قَالَ ‏ ‏أَبْشِرُوا ‏ ‏صَعَالِيكَ ‏ ‏الْمُهَاجِرِينَ ‏ ‏بِالْفَوْزِ يَوْمَ الْقِيَامَةِ عَلَى الْأَغْنِيَاءِ بِخَمْسِ مِائَةٍ أَحْسَبُهُ قَالَ سَنَةً ‏","","",""],[11480,11480,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَثَاءَبَ أَحَدُكُمْ فَلْيُمْسِكْ يَدَهُ عَلَى ‏ ‏فِيهِ فَإِنَّ الشَّيْطَانَ يَدْخُلُ ‏","","",""],[11481,11481,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏بِشْرُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏الْوِصَالِ ‏ ‏فِي الصَّوْمِ فَلَمْ يَزَلْ بِهِ أَصْحَابُهُ حَتَّى رَخَّصَ لَهُمْ مِنْ ‏ ‏السَّحَرِ ‏ ‏إِلَى ‏ ‏السَّحَرِ ‏","","",""],[11482,11482,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏افْتَخَرَ أَهْلُ الْإِبِلِ وَالْغَنَمِ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْفَخْرُ ‏ ‏وَالْخُيَلَاءُ ‏ ‏فِي أَهْلِ الْإِبِلِ ‏ ‏وَالسَّكِينَةُ ‏ ‏وَالْوَقَارُ فِي أَهْلِ الْغَنَمِ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بُعِثَ ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَهُوَ ‏ ‏يَرْعَى غَنَمًا عَلَى أَهْلِهِ وَبُعِثْتُ أَنَا وَأَنَا أَرْعَى غَنَمًا لِأَهْلِي ‏ ‏بِجِيَادٍ ‏","","",""],[11483,11483,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ الْغِلَابِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَرْضُ كُلُّهَا مَسْجِدٌ إِلَّا الْحَمَّامَ وَالْمَقْبَرَةَ ‏","","",""],[11484,11484,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يُوسُفَ بْنِ عَبْدِ اللَّهِ بْنِ سَلَامٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ جَاءَ جِنَازَةً فِي أَهْلِهَا فَتَبِعَهَا حَتَّى يُصَلِّيَ عَلَيْهَا فَلَهُ ‏ ‏قِيرَاطٌ ‏ ‏وَمَنْ مَضَى مَعَهَا فَلَهُ ‏ ‏قِيرَاطَانِ ‏ ‏مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[11485,11485,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏الْقَاسِمُ بْنُ الْفَضْلِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَمْرُقُ ‏ ‏مَارِقَةٌ ‏ ‏عِنْدَ فِرْقَةٍ مِنْ الْمُسْلِمِينَ تَقْتُلُهَا أَوْلَى الطَّائِفَتَيْنِ بِالْحَقِّ ‏","","",""],[11486,11486,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏أَمَرَنَا نَبِيُّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَقْرَأَ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏وَمَا تَيَسَّرَ ‏","","",""],[11487,11487,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏حَجَجْنَا فَنَزَلْنَا تَحْتَ ظِلِّ شَجَرَةٍ وَجَاءَ ‏ ‏ابْنُ صَائِدٍ ‏ ‏فَنَزَلَ إِلَى جَنْبِي قَالَ فَقُلْتُ مَا صَبَّ اللَّهُ هَذَا عَلَيَّ فَجَاءَنِي فَقَالَ يَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏أَمَا ‏ ‏تَرَى مَا أَلْقَى مِنْ النَّاسِ يَقُولُونَ أَنْتَ ‏ ‏الدَّجَّالُ ‏ ‏أَمَا سَمِعْتَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏الدَّجَّالَ ‏ ‏لَا يُولَدُ لَهُ وَلَا يَدْخُلُ ‏ ‏الْمَدِينَةَ ‏ ‏وَلَا ‏ ‏مَكَّةَ ‏ ‏وَقَدْ جِئْتُ الْآنَ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏وَأَنَا هُوَ ذَا أَذْهَبُ إِلَى ‏ ‏مَكَّةَ ‏ ‏وَقَدْ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏وَقَدْ دَخَلَ ‏ ‏مَكَّةَ ‏ ‏وَقَدْ وُلِدَ لِي حَتَّى رَقَقْتُ لَهُ ثُمَّ قَالَ وَاللَّهِ إِنَّ أَعْلَمَ النَّاسِ بِمَكَانِهِ السَّاعَةَ أَنَا فَقُلْتُ ‏ ‏تَبًّا ‏ ‏لَكَ سَائِرَ الْيَوْمِ ‏","","",""],[11488,11488,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْأَعْشَى ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ بُشَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ عَالَ ثَلَاثَ بَنَاتٍ فَأَدَّبَهُنَّ وَرَحِمَهُنَّ وَأَحْسَنَ إِلَيْهِنَّ فَلَهُ الْجَنَّةُ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏رَحِمَهُ اللَّهُ ‏ ‏مَاتَ ‏ ‏خَالِدُ بْنُ عَبْدِ اللَّهِ يَعْنِي الطَّحَّانَ ‏ ‏وَمَالِكُ بْنُ أَنَسٍ ‏ ‏وَأَبُو الْأَحْوَصِ ‏ ‏وَحَمَّادُ بْنُ زَيْدٍ ‏ ‏فِي سَنَةِ تِسْعٍ وَتِسْعِينَ إِلَّا أَنَّ ‏ ‏مَالِكًا ‏ ‏مَاتَ قَبْلَ ‏ ‏حَمَّادِ بْنِ زَيْدٍ ‏ ‏بِقَلِيلٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَفِي تِلْكَ السَّنَةِ طَلَبْتُ الْحَدِيثَ كُنَّا عَلَى بَابِ ‏ ‏هُشَيْمٍ ‏ ‏وَهُوَ ‏ ‏يُمْلِي عَلَيْنَا إِمَّا قَالَ الْجَنَائِزَ ‏ ‏أَوْ الْمَنَاسِكَ ‏ ‏فَجَاءَ رَجُلٌ بَصْرِيٌّ فَقَالَ مَاتَ ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏رَحْمَةُ اللَّهِ عَلَيْهِمْ أَجْمَعِينَ ‏","","",""],[11489,11489,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَبَا سَعِيدٍ ‏ ‏عَنْ الْإِزَارِ فَقَالَ عَلَى الْخَبِيرِ سَقَطْتَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِزْرَةُ الْمُؤْمِنِ إِلَى نِصْفِ السَّاقِ وَلَا حَرَجَ ‏ ‏أَوْ لَا جُنَاحَ ‏ ‏فِيمَا بَيْنَهُ وَبَيْنَ الْكَعْبَيْنِ مَا كَانَ أَسْفَلَ مِنْ الْكَعْبَيْنِ فَهُوَ فِي النَّارِ وَمَنْ جَرَّ إِزَارَهُ بَطَرًا لَمْ يَنْظُرْ اللَّهُ إِلَيْهِ ‏","","",""],[11490,11490,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِابْنِ صَائِدٍ ‏ ‏مَا ‏ ‏تَرَى قَالَ ‏ ‏أَرَى عَرْشًا عَلَى الْبَحْرِ حَوْلَهُ الْحَيَّاتُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاكَ عَرْشُ إِبْلِيسَ ‏","","",""],[11491,11491,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ ‏ ‏كَانَ جَالِسًا مَعَ ‏ ‏مَرْوَانَ ‏ ‏فَمَرَّتْ جِنَازَةٌ فَمَرَّ بِهِ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَقَالَ قُمْ أَيُّهَا الْأَمِيرُ فَقَدْ عَلِمَ هَذَا أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا تَبِعَ جِنَازَةً لَمْ يَجْلِسْ حَتَّى تُوضَعَ ‏","","",""],[11492,11492,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ مُسْلِمٍ الْعَبْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُتَوَكِّلِ النَّاجِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الذَّهَبُ بِالذَّهَبِ وَالْفِضَّةُ بِالْفِضَّةِ ‏ ‏وَالْبُرُّ ‏ ‏بِالْبُرِّ ‏ ‏وَالشَّعِيرُ بِالشَّعِيرِ وَالتَّمْرُ بِالتَّمْرِ وَالْمِلْحُ بِالْمِلْحِ مِثْلًا بِمِثْلٍ يَدًا بِيَدٍ فَمَنْ زَادَ أَوْ اسْتَزَادَ فَقَدْ أَرْبَى الْآخِذُ وَالْمُعْطِي فِيهِ سَوَاءٌ ‏","","",""],[11493,11493,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَحِلُّ ‏ ‏الصَّدَقَةُ ‏ ‏لِغَنِيٍّ إِلَّا ثَلَاثَةٍ فِي سَبِيلِ اللَّهِ أَوْ ابْنِ السَّبِيلِ أَوْ رَجُلٍ كَانَ لَهُ جَارٌ فَتُصُدِّقَ عَلَيْهِ فَأَهْدَى لَهُ ‏","","",""],[11494,11494,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِدْرِيسُ بْنُ يَزِيدَ الْأَوْدِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ فِيمَا دُونَ خَمْسَةِ ‏ ‏أَوْسَاقٍ ‏ ‏صَدَقَةٌ ‏","","",""],[11495,11495,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عُمَارَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ فِيمَا دُونَ خَمْسَةِ ‏ ‏أَوْسَاقٍ ‏ ‏مِنْ تَمْرٍ وَلَا حَبٍّ ‏ ‏صَدَقَةٌ ‏","","",""],[11496,11496,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ الْفَرَّاءُ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي سَرْحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا نُخْرِجُ ‏ ‏صَدَقَةَ ‏ ‏الْفِطْرِ إِذْ كَانَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَاعًا ‏ ‏مِنْ طَعَامٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ شَعِيرٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ زَبِيبٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ ‏ ‏أَقِطٍ ‏ ‏فَلَمْ نَزَلْ كَذَلِكَ حَتَّى قَدِمَ عَلَيْنَا ‏ ‏مُعَاوِيَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ الْفَرَّاءُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عِيَاضَ بْنَ عَبْدِ اللَّهِ بْنِ أَبِي سَرْحٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏كُنَّا نُخْرِجُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[11497,11497,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هَاشِمٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ رِيَاحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَوْ عَنْ غَيْرِهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا فَرَغَ مِنْ طَعَامِهِ قَالَ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مُسْلِمِينَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[11498,11498,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَدَّاكِ جَبْرُ بْنُ نَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏أَصَبْنَا حُمُرًا يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏فَكَانَتْ الْقُدُورُ تَغْلِي بِهَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا هَذِهِ فَقُلْنَا حُمُرٌ أَصَبْنَاهَا فَقَالَ وَحْشِيَّةٌ أَوْ أَهْلِيَّةٌ قَالَ قُلْنَا لَا بَلْ أَهْلِيَّةٌ قَالَ ‏ ‏اكْفِئُوهَا قَالَ فَكَفَأْنَاهَا ‏","","",""],[11499,11499,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏زَيْدٍ الْعَمِّيِّ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِرَجُلٍ فِي ‏ ‏حَدٍّ ‏ ‏قَالَ ‏ ‏فَضَرَبْنَا بِنَعْلَيْنِ أَرْبَعِينَ ‏ ‏قَالَ ‏ ‏مِسْعَرٌ ‏ ‏أَظُنُّهُ فِي شَرَابٍ ‏","","",""],[11500,11500,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِهِ ‏ { ‏يَوْمَ يَأْتِي بَعْضُ آيَاتِ رَبِّكَ لَا يَنْفَعُ نَفْسًا إِيمَانُهَا ‏} ‏قَالَ ‏ ‏طُلُوعُ الشَّمْسِ مِنْ مَغْرِبِهَا ‏","","",""],[11501,11501,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَهْلَ الدَّرَجَاتِ الْعُلَى يَرَاهُمْ مَنْ أَسْفَلَ مِنْهُمْ كَمَا تَرَوْنَ الْكَوْكَبَ الطَّالِعَ فِي الْأُفُقِ مِنْ آفَاقِ السَّمَاءِ وَإِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏مِنْهُمْ وَأَنْعَمَا ‏","","",""],[11502,11502,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏مُجَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ وَاللَّهِ مَا يَأْتِي عَلَيْنَا أَمِيرٌ إِلَّا وَهُوَ شَرٌّ مِنْ الْمَاضِي وَلَا عَامٌ إِلَّا وَهُوَ شَرٌّ مِنْ الْمَاضِي قَالَ لَوْلَا شَيْءٌ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقُلْتُ مِثْلَ مَا يَقُولُ وَلَكِنْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مِنْ أُمَرَائِكُمْ أَمِيرًا ‏ ‏يَحْثِي ‏ ‏الْمَالَ ‏ ‏حَثْيًا ‏ ‏وَلَا يَعُدُّهُ عَدًّا يَأْتِيهِ الرَّجُلُ فَيَسْأَلُهُ فَيَقُولُ خُذْ فَيَبْسُطُ الرَّجُلُ ثَوْبَهُ ‏ ‏فَيَحْثِي ‏ ‏فِيهِ وَبَسَطَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِلْحَفَةً ‏ ‏غَلِيظَةً كَانَتْ عَلَيْهِ يَحْكِي صَنِيعَ الرَّجُلِ ثُمَّ جَمَعَ إِلَيْهِ أَكْنَافَهَا قَالَ فَيَأْخُذُهُ ثُمَّ يَنْطَلِقُ ‏","","",""],[11503,11503,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏إِنْ كَانَتْ الْأَمَةُ مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏لَتَأْخُذُ بِيَدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَنْطَلِقُ بِهِ فِي حَاجَتِهَا ‏","","",""],[11504,11504,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏وَإِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[11505,11505,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِزَيْنَبَ ابْنَةِ جَحْشٍ ‏ ‏أَوْلَمَ ‏ ‏قَالَ فَأَطْعَمَنَا خُبْزًا وَلَحْمًا ‏","","",""],[11506,11506,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏يَرْفَعُ الْحَدِيثَ قَالَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يُرْفَعَ الْعِلْمُ وَيَظْهَرَ الْجَهْلُ وَيَقِلَّ الرِّجَالُ وَيَكْثُرَ النِّسَاءُ حَتَّى يَكُونَ ‏ ‏قَيِّمَ ‏ ‏خَمْسِينَ امْرَأَةً رَجُلٌ وَاحِدٌ ‏","","",""],[11507,11507,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي ‏ ‏بُرْدَةِ ‏ ‏حِبَرَةٍ ‏ ‏قَالَ أَحْسَبُهُ عَقَدَ بَيْنَ طَرَفَيْهَا ‏","","",""],[11508,11508,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَطُوفُ ‏ ‏عَلَى جَمِيعِ نِسَائِهِ فِي لَيْلَةٍ بِغُسْلٍ وَاحِدٍ ‏","","",""],[11509,11509,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا دَخَلَ ‏ ‏الْخَلَاءَ ‏ ‏قَالَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ‏ ‏الْخُبْثِ ‏ ‏وَالْخَبَائِثِ ‏","","",""],[11510,11510,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي بَكْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَلَّمَ عَلَيْكُمْ ‏ ‏أَهْلُ الْكِتَابِ ‏ ‏فَقُولُوا وَعَلَيْكُمْ ‏","","",""],[11511,11511,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏أَخْبَرَنَا عَنْ ‏ ‏أَنَسٍ ‏ ‏وَيُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْصُرْ أَخَاكَ ظَالِمًا أَوْ مَظْلُومًا قِيلَ يَا رَسُولَ اللَّهِ هَذَا أَنْصُرُهُ مَظْلُومًا فَكَيْفَ أَنْصُرُهُ إِذَا كَانَ ظَالِمًا قَالَ تَحْجُزُهُ تَمْنَعُهُ فَإِنَّ ذَلِكَ نَصْرُهُ ‏","","",""],[11512,11512,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏وَإِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسَحَّرُوا فَإِنَّ فِي السُّحُورِ بَرَكَةً ‏","","",""],[11513,11513,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الطَّوِيلِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ خَاتَمَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ فِضَّةٍ ‏","","",""],[11514,11514,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا اتَّخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَفِيَّةَ ‏ ‏أَقَامَ عِنْدَهَا ثَلَاثًا وَكَانَتْ ‏ ‏ثَيِّبًا ‏","","",""],[11515,11515,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ سَمِعْتُهُ يُحَدِّثُ قَالَ ‏ ‏شَهِدْتُ وَلِيمَتَيْنِ مِنْ نِسَاءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَمَا أَطْعَمَنَا فِيهَا خُبْزًا وَلَا لَحْمًا قَالَ قُلْتُ ‏ ‏فَمَهْ ‏ ‏قَالَ ‏ ‏الْحَيْسَ ‏ ‏يَعْنِي التَّمْرَ ‏ ‏وَالْأَقِطَ ‏ ‏بِالسَّمْنِ ‏","","",""],[11516,11516,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏الْعَوَّامُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَزْهَرُ بْنُ رَاشِدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَسْتَضِيئُوا بِنَارِ الْمُشْرِكِينَ وَلَا تَنْقُشُوا خَوَاتِيمَكُمْ عَرَبِيًّا ‏","","",""],[11517,11517,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلْتُ الْجَنَّةَ فَسَمِعْتُ ‏ ‏خَشْخَشَةً ‏ ‏بَيْنَ يَدَيَّ فَإِذَا هِيَ ‏ ‏الْغُمَيْصَاءُ بِنْتُ مِلْحَانَ ‏ ‏أُمُّ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏","","",""],[11518,11518,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُسِرَتْ ‏ ‏رَبَاعِيَتُهُ ‏ ‏يَوْمَ ‏ ‏أُحُدٍ ‏ ‏وَشُجَّ ‏ ‏فِي جَبْهَتِهِ حَتَّى سَالَ الدَّمُ عَلَى وَجْهِهِ فَقَالَ ‏ ‏كَيْفَ يُفْلِحُ قَوْمٌ فَعَلُوا هَذَا بِنَبِيِّهِمْ وَهُوَ يَدْعُوهُمْ إِلَى رَبِّهِمْ فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏لَيْسَ لَكَ مِنْ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ ‏}","","",""],[11519,11519,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْتَقَ ‏ ‏صَفِيَّةَ بِنْتَ حُيَيٍّ ‏ ‏وَجَعَلَ عِتْقَهَا ‏ ‏صَدَاقَهَا ‏","","",""],[11520,11520,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَبِي إِسْحَاقَ ‏ ‏وَعَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏وَحُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُمْ سَمِعُوهُ يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَبِّي بِالْحَجِّ وَالْعُمْرَةِ جَمِيعًا يَقُولُ ‏ ‏لَبَّيْكَ عُمْرَةً وَحَجًّا لَبَّيْكَ عُمْرَةً وَحَجًّا ‏","","",""],[11521,11521,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ وَأَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏وَأَظُنُّنِي قَدْ سَمِعْتُ مِنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِرَجُلٍ يَسُوقُ ‏ ‏بَدَنَةً ‏ ‏فَقَالَ ‏ ‏ارْكَبْهَا قَالَ إِنَّهَا بَدَنَةٌ قَالَ ارْكَبْهَا مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏","","",""],[11522,11522,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُضَحِّي ‏ ‏بِكَبْشَيْنِ أَقْرَنَيْنِ ‏ ‏أَمْلَحَيْنِ ‏ ‏وَكَانَ يُسَمِّي وَيُكَبِّرُ وَلَقَدْ رَأَيْتُهُ يَذْبَحُهُمَا بِيَدِهِ وَاضِعًا عَلَى ‏ ‏صِفَاحِهِمَا ‏ ‏قَدَمَهُ ‏","","",""],[11523,11523,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏بَكْرُ بْنُ عَبْدِ اللَّهِ الْمُزَنِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ ‏ ‏قَالَ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَبِّي بِالْحَجِّ وَالْعُمْرَةِ جَمِيعًا فَحَدَّثْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏بِذَلِكَ فَقَالَ لَبَّى بِالْحَجِّ وَحْدَهُ فَلَقِيتُ ‏ ‏أَنَسًا ‏ ‏فَحَدَّثْتُهُ بِقَوْلِ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَقَالَ مَا تَعُدُّونَا إِلَّا صِبْيَانًا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَبَّيْكَ عُمْرَةً وَحَجًّا ‏","","",""],[11524,11524,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏حَسِبْتُهُ ‏ ‏قَالَ عَطَسَ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلَانِ ‏ ‏فَشَمَّتَ ‏ ‏أَحَدَهُمَا ‏ ‏أَوْ قَالَ ‏ ‏سَمَّتَ ‏ ‏وَتَرَكَ الْآخَرَ فَقِيلَ رَجُلَانِ عَطَسَ أَحَدُهُمَا ‏ ‏فَشَمَّتَّهُ ‏ ‏وَلَمْ ‏ ‏تُشَمِّتْ ‏ ‏الْآخَرَ فَقَالَ ‏ ‏إِنَّ هَذَا حَمِدَ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[11525,11525,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ أَنْ يَلِيَهُ ‏ ‏الْمُهَاجِرُونَ ‏ ‏وَالْأَنْصَارُ ‏ ‏فِي الصَّلَاةِ ‏","","",""],[11526,11526,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَقَطَتْ لُقْمَةُ أَحَدِكُمْ فَلْيَأْخُذْهَا وَلْيَمْسَحْ مَا بِهَا مِنْ ‏ ‏الْأَذَى ‏ ‏وَلَا يَدَعْهَا لِلشَّيْطَانِ ‏","","",""],[11527,11527,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمْ يَكُنْ فِي رَأْسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلِحْيَتِهِ عِشْرُونَ شَعَرَةً بَيْضَاءَ ‏ ‏وَخَضَبَ ‏ ‏أَبُو بَكْرٍ ‏ ‏بِالْحِنَّاءِ وَالْكَتَمِ ‏ ‏وَخَضَبَ ‏ ‏عُمَرُ ‏ ‏بِالْحِنَّاءِ ‏","","",""],[11528,11528,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏حَجَمَ ‏ ‏أَبُو طَيْبَةَ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَعْطَاهُ صَاعًا مِنْ طَعَامٍ وَكَلَّمَ أَهْلَهُ فَخَفَّفُوا عَنْهُ ‏","","",""],[11529,11529,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَتَمِّ النَّاسِ صَلَاةً ‏ ‏وَأَوْجَزِهِ ‏","","",""],[11530,11530,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْأَخْضَرَ بْنَ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرٍ الْحَنَفِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَاعَ ‏ ‏قَدَحًا ‏ ‏وَحِلْسًا ‏ ‏فِيمَنْ يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَخْضَرِ ‏ ‏قَالَ ‏ ‏و حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ ‏ ‏يَعْنِي صَاحِبَ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏الْأَخْضَرِ بْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرٍ الْحَنَفِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[11531,11531,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏حَدَّثَنَا ‏ ‏غَالِبٌ الْقَطَّانُ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي شِدَّةِ الْحَرِّ فَإِذَا لَمْ يَسْتَطِعْ أَحَدُنَا أَنْ يُمَكِّنَ وَجْهَهُ مِنْ الْأَرْضِ ‏ ‏بَسَطَ ‏ ‏ثَوْبَهُ فَيَسْجُدُ عَلَيْهِ ‏","","",""],[11532,11532,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ الطُّفَاوِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وُضِعَ الْعَشَاءُ وَأُقِيمَتْ الصَّلَاةُ فَابْدَءُوا بِالْعَشَاءِ ‏","","",""],[11533,11533,"","","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا نَعَسَ أَحَدُكُمْ فِي صَلَاتِهِ فَلْيَنْصَرِفْ فَلْيَنَمْ ‏","","",""],[11534,11534,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ الْأَزْرَقُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عَرُوبَةَ ‏ ‏وَيَزِيدَ بْنِ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ نَسِيَ صَلَاةً أَوْ نَامَ عَنْهَا فَإِنَّمَا كَفَّارَتُهَا أَنْ يُصَلِّيَهَا إِذَا ذَكَرَهَا ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏فَكَفَّارَتُهَا أَنْ ‏","","",""],[11535,11535,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى ‏ ‏لَيَرْضَى عَنْ الْعَبْدِ أَنْ يَأْكُلَ الْأُكْلَةَ فَيَحْمَدَ اللَّهَ عَزَّ وَجَلَّ عَلَيْهَا أَوْ يَشْرَبَ الشَّرْبَةَ ‏","","",""],[11536,11536,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ الْأَزْرَقُ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏خَدَمْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِسْعَ سِنِينَ ‏ ‏فَمَا أَعْلَمُهُ قَالَ لِي قَطُّ هَلَّا فَعَلْتَ كَذَا وَكَذَا وَلَا عَابَ عَلَيَّ شَيْئًا قَطُّ ‏","","",""],[11537,11537,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ رُفَيْعٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قُلْتُ ‏ ‏أَخْبِرْنِي بِشَيْءٍ ‏ ‏عَقِلْتَهُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيْنَ صَلَّى الظُّهْرَ يَوْمَ ‏ ‏التَّرْوِيَةِ ‏ ‏قَالَ ‏ ‏بِمِنًى ‏ ‏وَأَيْنَ صَلَّى الْعَصْرَ يَوْمَ ‏ ‏النَّفْرِ ‏ ‏قَالَ ‏ ‏بِالْأَبْطَحِ ‏ ‏قَالَ ثُمَّ قَالَ افْعَلْ كَمَا يَفْعَلُ أُمَرَاؤُكَ ‏","","",""],[11538,11538,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏وَغَسَّانُ بْنُ مُضَرَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَزِيدَ أَبِي مَسْلَمَةَ ‏ ‏قَالَ قُلْتُ ‏ ‏لِأَنَسِ بْنِ مَالِكٍ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي نَعْلَيْهِ قَالَ ‏ ‏نَعَمْ ‏","","",""],[11539,11539,"","","‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ الرَّبِيعِ أَبُو خِدَاشٍ الْيُحْمَدِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عِمْرَانَ الْجَوْنِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏مَا أَعْرِفُ شَيْئًا الْيَوْمَ مِمَّا كُنَّا عَلَيْهِ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قُلْنَا لَهُ فَأَيْنَ الصَّلَاةُ قَالَ أَوَلَمْ تَصْنَعُوا فِي الصَّلَاةِ مَا قَدْ عَلِمْتُمْ ‏","","",""],[11540,11540,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏نَهَى نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَتَزَعْفَرَ الرَّجُلُ ‏","","",""],[11541,11541,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَتَمَنَّى أَحَدُكُمْ الْمَوْتَ لِضُرٍّ نَزَلَ بِهِ فَإِنْ كَانَ لَا بُدَّ مُتَمَنِّيَ الْمَوْتِ فَلْيَقُلْ اللَّهُمَّ أَحْيِنِي مَا كَانَتْ الْحَيَاةُ خَيْرًا لِي وَتَوَفَّنِي إِذَا كَانَتْ الْوَفَاةُ خَيْرًا لِي ‏","","",""],[11542,11542,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَعَا أَحَدُكُمْ ‏ ‏فَلْيَعْزِمْ ‏ ‏فِي الدُّعَاءِ وَلَا يَقُلْ اللَّهُمَّ إِنْ شِئْتَ فَأَعْطِنِي فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَا مُسْتَكْرِهَ لَهُ ‏","","",""],[11543,11543,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏قَالَ سَأَلَ ‏ ‏قَتَادَةُ ‏ ‏أَنَسًا ‏ ‏أَيُّ دَعْوَةٍ كَانَ أَكْثَرَ يَدْعُو بِهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَانَ أَكْثَرُ دَعْوَةٍ يَدْعُو بِهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ ‏ ‏وَكَانَ ‏ ‏أَنَسٌ ‏ ‏إِذَا أَرَادَ أَنْ يَدْعُوَ بِدَعْوَةٍ دَعَا بِهَا وَإِذَا أَرَادَ أَنْ يَدْعُوَ بِدُعَاءٍ دَعَا بِهَا فِيهِ ‏","","",""],[11544,11544,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مُعَاذٌ ‏ ‏يَؤُمُّ قَوْمَهُ فَدَخَلَ ‏ ‏حَرَامٌ ‏ ‏وَهُوَ يُرِيدُ أَنْ يَسْقِيَ نَخْلَهُ فَدَخَلَ الْمَسْجِدَ لِيُصَلِّيَ مَعَ الْقَوْمِ فَلَمَّا رَأَى ‏ ‏مُعَاذًا ‏ ‏طَوَّلَ ‏ ‏تَجَوَّزَ ‏ ‏فِي صَلَاتِهِ وَلَحِقَ بِنَخْلِهِ ‏ ‏يَسْقِيهِ فَلَمَّا ‏ ‏قَضَى ‏ ‏مُعَاذٌ ‏ ‏صَلَاتَهُ قِيلَ لَهُ إِنَّ ‏ ‏حَرَامًا ‏ ‏دَخَلَ الْمَسْجِدَ ‏","","",""],[11545,11545,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ ‏ ‏الْخَلَاءَ ‏ ‏قَالَ ‏ ‏أَعُوذُ بِاللَّهِ مِنْ ‏ ‏الْخُبْثِ ‏ ‏وَالْخَبَائِثِ ‏","","",""],[11546,11546,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُضَحِّي ‏ ‏بِكَبْشَيْنِ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏وَأَنَا أُضَحِّي بِكَبْشَيْنِ ‏","","",""],[11547,11547,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا فَلَنْ يَلْبَسَهُ فِي الْآخِرَةِ ‏","","",""],[11548,11548,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَسْجِدَ وَحَبْلٌ مَمْدُودٌ بَيْنَ ‏ ‏سَارِيَتَيْنِ ‏ ‏فَقَالَ مَا هَذَا قَالُوا ‏ ‏لِزَيْنَبَ ‏ ‏تُصَلِّي فَإِذَا كَسِلَتْ ‏ ‏أَوْ ‏ ‏فَتَرَتْ ‏ ‏أَمْسَكَتْ بِهِ فَقَالَ حُلُّوهُ ثُمَّ قَالَ ‏ ‏لِيُصَلِّ أَحَدُكُمْ نَشَاطَهُ فَإِذَا كَسِلَ ‏ ‏أَوْ ‏ ‏فَتَرَ ‏ ‏فَلْيَقْعُدْ ‏","","",""],[11549,11549,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَجِيٌّ لِرَجُلٍ فِي الْمَسْجِدِ ‏ ‏فَمَا قَامَ إِلَى الصَّلَاةِ حَتَّى قَامَ الْقَوْمُ ‏","","",""],[11550,11550,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏أَخَذَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏بِيَدِي فَانْطَلَقَ بِي إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَنَسًا ‏ ‏غُلَامٌ ‏ ‏كَيِّسٌ ‏ ‏فَلْيَخْدُمْكَ قَالَ فَخَدَمْتُهُ فِي السَّفَرِ وَالْحَضَرِ ‏ ‏وَاللَّهِ مَا قَالَ لِي لِشَيْءٍ صَنَعْتُهُ لِمَ صَنَعْتَ هَذَا هَكَذَا وَلَا لِشَيْءٍ لَمْ أَصْنَعْهُ لِمَ لَمْ تَصْنَعْ هَذَا هَكَذَا ‏","","",""],[11551,11551,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏اصْطَنَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمًا فَقَالَ إِنَّا ‏ ‏قَدْ اصْطَنَعْنَا خَاتَمًا وَنَقَشْنَا فِيهِ نَقْشًا فَلَا يَنْقُشُ أَحَدٌ عَلَيْهِ ‏","","",""],[11552,11552,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوجِزُ الصَّلَاةَ وَيُكْمِلُهَا ‏","","",""],[11553,11553,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏كَانُوا ‏ ‏يَفْتَتِحُونَ الْقِرَاءَةَ بِ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏}","","",""],[11554,11554,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَزَا ‏ ‏خَيْبَرَ ‏ ‏فَصَلَّيْنَا عِنْدَهَا صَلَاةَ ‏ ‏الْغَدَاةِ ‏ ‏بِغَلَسٍ ‏ ‏فَرَكِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَكِبَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏وَأَنَا ‏ ‏رَدِيفُ ‏ ‏أَبِي طَلْحَةَ ‏ ‏فَأَجْرَى نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏زُقَاقِ ‏ ‏خَيْبَرَ ‏ ‏وَإِنَّ رُكْبَتَيَّ لَتَمَسُّ فَخِذَيْ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَانْحَسَرَ ‏ ‏الْإِزَارُ ‏ ‏عَنْ فَخِذَيْ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنِّي لَأَرَى بَيَاضَ فَخِذَيْ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا دَخَلَ الْقَرْيَةَ قَالَ اللَّهُ أَكْبَرُ خَرِبَتْ ‏ ‏خَيْبَرُ ‏ ‏إِنَّا إِذَا نَزَلْنَا ‏ ‏بِسَاحَةِ ‏ ‏قَوْمٍ ‏ ‏فَسَاءَ ‏ ‏صَبَاحُ الْمُنْذَرِينَ قَالَهَا ثَلَاثَ مِرَارٍ قَالَ وَقَدْ خَرَجَ الْقَوْمُ إِلَى أَعْمَالِهِمْ فَقَالُوا ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏وَقَالَ بَعْضُ أَصْحَابِنَا ‏ ‏الْخُمُسُ ‏ ‏قَالَ فَأَصَبْنَاهَا ‏ ‏عَنْوَةً ‏ ‏فَجُمِعَ ‏ ‏السَّبْيُ ‏ ‏قَالَ فَجَاءَ ‏ ‏دِحْيَةُ ‏ ‏فَقَالَ يَا نَبِيَّ اللَّهِ أَعْطِنِي جَارِيَةً مِنْ ‏ ‏السَّبْيِ ‏ ‏قَالَ اذْهَبْ فَخُذْ جَارِيَةً قَالَ فَأَخَذَ ‏ ‏صَفِيَّةَ بِنْتَ حُيَيٍّ ‏ ‏فَجَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَعْطَيْتَ ‏ ‏دِحْيَةَ ‏ ‏صَفِيَّةَ بِنْتَ حُيَيٍّ ‏ ‏سَيِّدَةَ ‏ ‏قُرَيْظَةَ ‏ ‏وَالنَّضِيرِ ‏ ‏وَاللَّهِ مَا تَصْلُحُ إِلَّا لَكَ فَقَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ادْعُوهُ بِهَا فَجَاءَ بِهَا فَلَمَّا نَظَرَ إِلَيْهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ خُذْ جَارِيَةً مِنْ ‏ ‏السَّبْيِ ‏ ‏غَيْرَهَا ثُمَّ إِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْتَقَهَا وَتَزَوَّجَهَا فَقَالَ لَهُ ‏ ‏ثَابِتٌ ‏ ‏يَا ‏ ‏أَبَا حَمْزَةَ ‏ ‏مَا ‏ ‏أَصْدَقَهَا ‏ ‏قَالَ نَفْسَهَا أَعْتَقَهَا وَتَزَوَّجَهَا حَتَّى إِذَا كَانَ بِالطَّرِيقِ جَهَّزَتْهَا ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏فَأَهْدَتْهَا لَهُ مِنْ اللَّيْلِ وَأَصْبَحَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَرُوسًا فَقَالَ مَنْ كَانَ عِنْدَهُ شَيْءٌ فَلْيَجِئْ بِهِ وَبَسَطَ نِطَعًا فَجَعَلَ الرَّجُلُ يَجِيءُ ‏ ‏بِالْأَقِطِ ‏ ‏وَجَعَلَ الرَّجُلُ يَجِيءُ بِالتَّمْرِ وَجَعَلَ الرَّجُلُ يَجِيءُ بِالسَّمْنِ ‏ ‏قَالَ وَأَحْسِبُهُ قَدْ ذَكَرَ ‏ ‏السَّوِيقَ ‏ ‏قَالَ ‏ ‏فَحَاسُوا ‏ ‏حَيْسًا ‏ ‏وَكَانَتْ وَلِيمَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[11555,11555,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏أَخْبَرَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏دِرْعُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرْهُونَةً مَا وَجَدَ مَا يَفْتَكُّهَا حَتَّى مَاتَ ‏","","",""],[11556,11556,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُخْتَارُ بْنُ فُلْفُلٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْكَوْثَرُ نَهَرٌ فِي الْجَنَّةِ وَعَدَنِيهِ رَبِّي عَزَّ وَجَلَّ ‏","","",""],[11557,11557,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏الْمُخْتَارِ بْنِ فُلْفُلٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ تَعَالَى قَالَ لِي ‏ ‏إِنَّ أُمَّتَكَ لَا يَزَالُونَ يَتَسَاءَلُونَ فِيمَا بَيْنَهُمْ حَتَّى يَقُولُوا هَذَا اللَّهُ خَلَقَ النَّاسَ فَمَنْ خَلَقَ اللَّهَ ‏","","",""],[11558,11558,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏الْمُخْتَارِ بْنِ فُلْفُلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏أَغْفَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِغْفَاءَةً فَرَفَعَ رَأْسَهُ مُتَبَسِّمًا ‏ ‏إِمَّا قَالَ لَهُمْ وَإِمَّا قَالُوا لَهُ ‏ ‏لِمَ ضَحِكْتَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ أُنْزِلَتْ عَلَيَّ آنِفًا سُورَةٌ فَقَرَأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏ ‏إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ‏ ‏حَتَّى خَتَمَهَا قَالَ هَلْ تَدْرُونَ مَا الْكَوْثَرُ قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏هُوَ نَهْرٌ أَعْطَانِيهِ رَبِّي عَزَّ وَجَلَّ فِي الْجَنَّةِ عَلَيْهِ خَيْرٌ كَثِيرٌ يَرِدُ عَلَيْهِ أُمَّتِي يَوْمَ الْقِيَامَةِ آنِيَتُهُ عَدَدُ الْكَوَاكِبِ يُخْتَلَجُ الْعَبْدُ مِنْهُمْ فَأَقُولُ يَا رَبِّ إِنَّهُ مِنْ أُمَّتِي فَيُقَالُ لِي إِنَّكَ لَا تَدْرِي مَا ‏ ‏أَحْدَثُوا ‏ ‏بَعْدَكَ ‏","","",""],[11559,11559,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُخْتَارُ بْنُ فُلْفُلٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ وَقَدْ انْصَرَفَ مِنْ الصَّلَاةِ فَأَقْبَلَ إِلَيْنَا فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِنِّي إِمَامُكُمْ فَلَا تَسْبِقُونِي بِالرُّكُوعِ وَلَا بِالسُّجُودِ وَلَا بِالْقِيَامِ وَلَا بِالْقُعُودِ وَلَا ‏ ‏بِالِانْصِرَافِ فَإِنِّي أَرَاكُمْ مِنْ أَمَامِي وَمِنْ خَلْفِي وَايْمُ الَّذِي نَفْسِي بِيَدِهِ لَوْ رَأَيْتُمْ مَا رَأَيْتُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا قَالُوا يَا رَسُولَ اللَّهِ وَمَا رَأَيْتَ قَالَ رَأَيْتُ الْجَنَّةَ وَالنَّارَ ‏","","",""],[11560,11560,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ عَمْرٍو يَعْنِي ابْنَ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏بُرَيْدِ بْنِ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى عَلَيَّ صَلَاةً وَاحِدَةً صَلَّى اللَّهُ عَلَيْهِ عَشْرَ صَلَوَاتٍ وَحَطَّ عَنْهُ عَشْرَ خَطِيئَاتٍ ‏","","",""],[11561,11561,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏دَخَلْنَا عَلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَا وَرَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏حِينَ صَلَّيْنَا الظُّهْرَ فَدَعَا ‏ ‏الْجَارِيَةَ ‏ ‏بِوَضُوءٍ ‏ ‏فَقُلْنَا لَهُ أَيُّ صَلَاةٍ تُصَلِّي قَالَ الْعَصْرَ قَالَ قُلْنَا إِنَّمَا صَلَّيْنَا الظُّهْرَ الْآنَ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تِلْكَ صَلَاةُ الْمُنَافِقِ يَتْرُكُ الصَّلَاةَ حَتَّى إِذَا كَانَتْ فِي قَرْنَيْ الشَّيْطَانِ ‏ ‏أَوْ بَيْنَ قَرْنَيْ الشَّيْطَانِ ‏ ‏صَلَّى لَا يَذْكُرُ اللَّهَ فِيهَا إِلَّا قَلِيلًا ‏","","",""],[11562,11562,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَبْدِ الْمَجِيدِ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ عَلَى ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏فَتَبْسُطُ لَهُ نِطْعًا فَيَقِيلُ عَلَيْهِ فَتَأْخُذُ مِنْ عَرَقِهِ فَتَجْعَلُهُ فِي طِيبِهَا ‏ ‏وَتَبْسُطُ لَهُ ‏ ‏الْخُمْرَةَ ‏ ‏فَيُصَلِّي عَلَيْهَا ‏","","",""],[11563,11563,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أُمِرَ ‏ ‏بِلَالٌ ‏ ‏أَنْ يَشْفَعَ الْأَذَانَ ‏ ‏وَيُوتِرَ ‏ ‏الْإِقَامَةَ ‏","","",""],[11564,11564,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ثَلَاثٌ مَنْ كُنَّ فِيهِ وَجَدَ بِهِنَّ حَلَاوَةَ الْإِيمَانِ ‏ ‏أَنْ يَكُونَ اللَّهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا وَأَنْ يُحِبَّ الْمَرْءَ لَا يُحِبُّهُ إِلَّا لِلَّهِ وَأَنْ يَكْرَهَ أَنْ يَعُودَ فِي الْكُفْرِ بَعْدَ إِذْ أَنْقَذَهُ اللَّهُ مِنْهُ كَمَا يَكْرَهُ أَنْ يُوقَدَ لَهُ نَارٌ فَيُقْذَفَ فِيهَا ‏","","",""],[11565,11565,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْهَيْثَمِ أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ أَحَدٍ يَدْخُلُ الْجَنَّةَ يُحِبُّ أَنْ يَخْرُجَ مِنْهَا وَإِنَّ لَهُ مَا عَلَى الْأَرْضِ مِنْ شَيْءٍ غَيْرَ الشَّهِيدِ يُحِبُّ أَنْ يَخْرُجَ فَيُقْتَلَ لِمَا يَرَى مِنْ الْكَرَامَةِ أَوْ مَعْنَاهُ ‏","","",""],[11566,11566,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْهَيْثَمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا بُعِثَ نَبِيٌّ إِلَّا أَنْذَرَ أُمَّتَهُ الْأَعْوَرَ الْكَذَّابَ أَلَا إِنَّهُ أَعْوَرُ وَإِنَّ رَبَّكُمْ لَيْسَ بِأَعْوَرَ مَكْتُوبٌ بَيْنَ عَيْنَيْهِ كَافِرٌ ‏","","",""],[11567,11567,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي ذَاتَ لَيْلَةٍ فِي حُجْرَتِهِ فَجَاءَ أُنَاسٌ فَصَلَّوْا بِصَلَاتِهِ فَخَفَّفَ فَدَخَلَ الْبَيْتَ ثُمَّ خَرَجَ فَعَادَ مِرَارًا كُلَّ ذَلِكَ ‏ ‏يُصَلِّي فَلَمَّا أَصْبَحَ قَالُوا يَا رَسُولَ اللَّهِ صَلَّيْتَ وَنَحْنُ نُحِبُّ أَنْ تَمُدَّ فِي صَلَاتِكَ قَالَ قَدْ ‏ ‏عَلِمْتُ بِمَكَانِكُمْ وَعَمْدًا فَعَلْتُ ذَلِكَ ‏","","",""],[11568,11568,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَلَهُمْ يَوْمَانِ يَلْعَبُونَ فِيهِمَا فِي الْجَاهِلِيَّةِ فَقَالَ ‏ ‏إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى قَدْ أَبْدَلَكُمْ بِهِمَا خَيْرًا مِنْهُمَا يَوْمَ الْفِطْرِ وَيَوْمَ ‏ ‏النَّحْرِ ‏","","",""],[11569,11569,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَائِطًا مِنْ ‏ ‏حِيطَانِ ‏ ‏بَنِي النَّجَّارِ ‏ ‏فَسَمِعَ صَوْتًا مِنْ قَبْرٍ فَسَأَلَ عَنْهُ مَتَى دُفِنَ هَذَا فَقَالُوا يَا رَسُولَ اللَّهِ دُفِنَ هَذَا فِي الْجَاهِلِيَّةِ فَأَعْجَبَهُ ذَلِكَ وَقَالَ ‏ ‏لَوْلَا أَنْ لَا تَدَافَنُوا لَدَعَوْتُ اللَّهَ عَزَّ وَجَلَّ أَنْ يُسْمِعَكُمْ عَذَابَ الْقَبْرِ ‏","","",""],[11570,11570,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلْتُ الْجَنَّةَ فَإِذَا أَنَا بِنَهْرٍ حَافَتَاهُ خِيَامُ اللُّؤْلُؤِ فَضَرَبْتُ بِيَدِي إِلَى مَا يَجْرِي فِيهِ الْمَاءُ فَإِذَا ‏ ‏مِسْكٌ ‏ ‏أَذْفَرُ ‏ ‏قُلْتُ مَا هَذَا يَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ هَذَا الْكَوْثَرُ الَّذِي أَعْطَاكَهُ اللَّهُ ‏","","",""],[11571,11571,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا رَجَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏فَدَنَا مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏بِالْمَدِينَةِ ‏ ‏لَقَوْمًا مَا سِرْتُمْ مَسِيرًا وَلَا قَطَعْتُمْ وَادِيًا إِلَّا كَانُوا مَعَكُمْ فِيهِ قَالُوا يَا رَسُولَ اللَّهِ وَهُمْ ‏ ‏بِالْمَدِينَةِ ‏ ‏قَالَ وَهُمْ ‏ ‏بِالْمَدِينَةِ ‏ ‏حَبَسَهُمْ الْعُذْرُ ‏","","",""],[11572,11572,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَتْ نَاقَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُسَمَّى ‏ ‏الْعَضْبَاءَ ‏ ‏وَكَانَتْ لَا تُسْبَقُ فَجَاءَ أَعْرَابِيٌّ عَلَى ‏ ‏قَعُودٍ ‏ ‏فَسَبَقَهَا فَشَقَّ ذَلِكَ عَلَى الْمُسْلِمِينَ فَلَمَّا رَأَى مَا فِي وُجُوهِهِمْ قَالُوا يَا رَسُولَ اللَّهِ سُبِقَتْ ‏ ‏الْعَضْبَاءُ ‏ ‏فَقَالَ ‏ ‏إِنَّ حَقًّا عَلَى اللَّهِ أَنْ لَا يَرْفَعَ شَيْئًا مِنْ الدُّنْيَا إِلَّا وَضَعَهُ ‏","","",""],[11573,11573,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ فَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَقَالَ ‏ ‏أَقِيمُوا صُفُوفَكُمْ وَتَرَاصُّوا فَإِنِّي أَرَاكُمْ مِنْ وَرَاءِ ظَهْرِي ‏","","",""],[11574,11574,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسٌ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ اللَّيْلِ فَقَالَ ‏ ‏مَا كُنَّا نَشَاءُ أَنْ ‏ ‏نَرَاهُ مِنْ اللَّيْلِ مُصَلِّيًا إِلَّا رَأَيْنَاهُ وَمَا كُنَّا نَشَاءُ أَنْ ‏ ‏نَرَاهُ نَائِمًا إِلَّا رَأَيْنَاهُ وَكَانَ يَصُومُ مِنْ الشَّهْرِ حَتَّى نَقُولَ لَا يُفْطِرُ مِنْهُ شَيْئًا وَيُفْطِرُ حَتَّى نَقُولَ لَا يَصُومُ مِنْهُ شَيْئًا ‏","","",""],[11575,11575,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ يُعْجِبُنَا أَنْ يَجِيءَ الرَّجُلُ مِنْ أَهْلِ ‏ ‏الْبَادِيَةِ ‏ ‏فَيَسْأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ ‏ ‏أَعْرَابِيٌّ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ مَتَى قِيَامُ السَّاعَةِ وَأُقِيمَتْ الصَّلَاةُ فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا فَرَغَ مِنْ صَلَاتِهِ قَالَ أَيْنَ السَّائِلُ عَنْ السَّاعَةِ قَالَ أَنَا يَا رَسُولَ اللَّهِ قَالَ وَمَا أَعْدَدْتَ لَهَا قَالَ مَا أَعْدَدْتُ لَهَا مِنْ كَثِيرِ عَمَلٍ لَا صَلَاةٍ وَلَا صِيَامٍ إِلَّا أَنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَرْءُ مَعَ مَنْ أَحَبَّ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَمَا رَأَيْتُ الْمُسْلِمِينَ فَرِحُوا بَعْدَ الْإِسْلَامِ بِشَيْءٍ مَا فَرِحُوا بِهِ ‏","","",""],[11576,11576,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ وَقَدْ كَانَ بَيْنَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَيْنَ نِسَائِهِ شَيْءٌ ‏ ‏فَجَعَلَ يَرُدُّ بَعْضَهُنَّ عَنْ بَعْضٍ فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَقَالَ احْثُ يَا رَسُولَ اللَّهِ فِي أَفْوَاهِهِنَّ التُّرَابَ وَاخْرُجْ إِلَى الصَّلَاةِ ‏","","",""],[11577,11577,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَتَمَنَّيَنَّ أَحَدُكُمْ الْمَوْتَ لِضُرٍّ نَزَلَ بِهِ وَلَكِنْ لِيَقُلْ اللَّهُمَّ أَحْيِنِي مَا كَانَتْ الْحَيَاةُ خَيْرًا لِي وَتَوَفَّنِي إِذَا كَانَتْ الْوَفَاةُ خَيْرًا لِي ‏","","",""],[11578,11578,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يُكْثِرُ الصَّوْمَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا مَاتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ لَا يُفْطِرُ إِلَّا فِي سَفَرٍ أَوْ مَرَضٍ ‏","","",""],[11579,11579,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ مُقِيمًا ‏ ‏اعْتَكَفَ ‏ ‏الْعَشْرَ الْأَوَاخِرَ مِنْ رَمَضَانَ وَإِذَا سَافَرَ ‏ ‏اعْتَكَفَ ‏ ‏مِنْ الْعَامِ الْمُقْبِلِ عِشْرِينَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏لَمْ أَسْمَعْ هَذَا الْحَدِيثَ إِلَّا مِنْ ‏ ‏ابْنِ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏","","",""],[11580,11580,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مَرَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏نَفَرٍ ‏ ‏مِنْ أَصْحَابِهِ وَصَبِيٌّ فِي الطَّرِيقِ فَلَمَّا رَأَتْ أُمُّهُ الْقَوْمَ خَشِيَتْ عَلَى وَلَدِهَا أَنْ ‏ ‏يُوطَأَ ‏ ‏فَأَقْبَلَتْ ‏ ‏تَسْعَى وَتَقُولُ ابْنِي ابْنِي وَسَعَتْ فَأَخَذَتْهُ فَقَالَ الْقَوْمُ يَا رَسُولَ اللَّهِ مَا كَانَتْ هَذِهِ لِتُلْقِيَ ابْنَهَا فِي النَّارِ قَالَ فَخَفَّضَهُمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏وَلَاءُ ‏ ‏اللَّهِ عَزَّ وَجَلَّ لَا يُلْقِي حَبِيبَهُ فِي النَّارِ ‏","","",""],[11581,11581,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسٌ ‏ ‏هَلْ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْفَعُ يَدَيْهِ فَقَالَ قِيلَ لَهُ يَوْمَ الْجُمُعَةِ يَا رَسُولَ اللَّهِ ‏ ‏قَحَطَ ‏ ‏الْمَطَرُ وَأَجْدَبَتْ الْأَرْضُ وَهَلَكَ الْمَالُ قَالَ ‏ ‏فَرَفَعَ يَدَيْهِ حَتَّى رَأَيْتُ بَيَاضَ إِبْطَيْهِ فَاسْتَسْقَى وَلَقَدْ رَفَعَ يَدَيْهِ فَاسْتَسْقَى وَلَقَدْ رَفَعَ يَدَيْهِ وَمَا نَرَى فِي السَّمَاءِ سَحَابَةً فَلَمَّا قَضَيْنَا الصَّلَاةَ حَتَّى إِنَّ قَرِيبَ الدَّارِ الشَّابَّ لَيُهِمُّهُ الرُّجُوعَ إِلَى أَهْلِهِ قَالَ فَلَمَّا كَانَتْ الْجُمُعَةُ الَّتِي تَلِيهَا قَالُوا يَا رَسُولَ اللَّهِ تَهَدَّمَتْ الْبُيُوتُ وَاحْتُبِسَتْ ‏ ‏الرُّكْبَانُ ‏ ‏فَتَبَسَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ سُرْعَةِ مَلَالَةِ ابْنِ ‏ ‏آدَمَ ‏ ‏وَقَالَ اللَّهُمَّ ‏ ‏حَوَالَيْنَا ‏ ‏وَلَا عَلَيْنَا ‏ ‏فَتَكَشَّطَتْ ‏ ‏عَنْ ‏ ‏الْمَدِينَةِ ‏","","",""],[11582,11582,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سَمِعَ الْمُسْلِمُونَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يُنَادِي عَلَى ‏ ‏قَلِيبِ بَدْرٍ ‏ ‏يَا ‏ ‏أَبَا جَهْلِ بْنَ هِشَامٍ ‏ ‏يَا ‏ ‏عُتْبَةُ بْنَ رَبِيعَةَ ‏ ‏يَا ‏ ‏شَيْبَةُ بْنَ رَبِيعَةَ ‏ ‏يَا ‏ ‏أُمَيَّةُ بْنَ خَلَفٍ ‏ ‏هَلْ وَجَدْتُمْ مَا وَعَدَكُمْ رَبُّكُمْ حَقًّا فَإِنِّي وَجَدْتُ مَا وَعَدَنِي رَبِّي حَقًّا قَالُوا يَا رَسُولَ اللَّهِ تُنَادِي قَوْمًا قَدْ ‏ ‏جَيَّفُوا ‏ ‏قَالَ ‏ ‏مَا أَنْتُمْ بِأَسْمَعَ لِمَا أَقُولُ مِنْهُمْ وَلَكِنَّهُمْ لَا يَسْتَطِيعُونَ أَنْ يُجِيبُوا ‏","","",""],[11583,11583,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏أَلَمْ آتِكُمْ ضُلَّالًا فَهَدَاكُمْ اللَّهُ عَزَّ وَجَلَّ بِي أَلَمْ آتِكُمْ مُتَفَرِّقِينَ فَجَمَعَكُمْ اللَّهُ بِي أَلَمْ آتِكُمْ أَعْدَاءً فَأَلَّفَ اللَّهُ بَيْنَ قُلُوبِكُمْ بِي قَالُوا بَلَى ‏ ‏يَا رَسُولَ اللَّهِ قَالَ أَفَلَا تَقُولُونَ جِئْتَنَا خَائِفًا فَآمَنَّاكَ وَطَرِيدًا فَآوَيْنَاكَ وَمَخْذُولًا فَنَصَرْنَاكَ فَقَالُوا بَلْ لِلَّهِ تَبَارَكَ وَتَعَالَى ‏ ‏الْمَنُّ ‏ ‏بِهِ عَلَيْنَا وَلِرَسُولِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[11584,11584,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا سَارَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏بَدْرٍ ‏ ‏خَرَجَ ‏ ‏فَاسْتَشَارَ النَّاسَ فَأَشَارَ عَلَيْهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏ثُمَّ اسْتَشَارَهُمْ فَأَشَارَ عَلَيْهِ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَسَكَتَ فَقَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏إِنَّمَا يُرِيدُكُمْ فَقَالُوا يَا رَسُولَ اللَّهِ وَاللَّهِ لَا نَكُونُ كَمَا قَالَتْ ‏ ‏بَنُو إِسْرَائِيلَ ‏ ‏لِمُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ { ‏اذْهَبْ أَنْتَ وَرَبُّكَ فَقَاتِلَا إِنَّا هَاهُنَا قَاعِدُونَ ‏} ‏وَلَكِنْ وَاللَّهِ لَوْ ضَرَبْتَ أَكْبَادَ الْإِبِلِ حَتَّى تَبْلُغَ ‏ ‏بَرْكَ الْغِمَادِ ‏ ‏لَكُنَّا مَعَكَ ‏","","",""],[11585,11585,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏دَعَوْتُ الْمُسْلِمِينَ إِلَى ‏ ‏وَلِيمَةِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَبِيحَةَ بَنَى ‏ ‏بِزَيْنَبَ بِنْتِ جَحْشٍ ‏ ‏فَأَشْبَعَ الْمُسْلِمِينَ خُبْزًا وَلَحْمًا قَالَ ثُمَّ رَجَعَ كَمَا كَانَ يَصْنَعُ فَأَتَى ‏ ‏حُجَرَ ‏ ‏نِسَائِهِ فَسَلَّمَ عَلَيْهِنَّ فَدَعَوْنَ لَهُ قَالَ ثُمَّ رَجَعَ إِلَى بَيْتِهِ وَأَنَا مَعَهُ فَلَمَّا انْتَهَى إِلَى الْبَيْتِ فَإِذَا رَجُلَانِ قَدْ جَرَى بَيْنَهُمَا الْحَدِيثُ فِي نَاحِيَةِ الْبَيْتِ فَلَمَّا بَصَرَ بِهِمَا وَلَّى رَاجِعًا فَلَمَّا رَأَى الرَّجُلَانِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ وَلَّى عَنْ بَيْتِهِ قَامَا مُسْرِعَيْنِ ‏ ‏فَلَا أَدْرِي أَنَا أَخْبَرْتُهُ أَوْ أُخْبِرَ بِهِ ‏ ‏ثُمَّ رَجَعَ إِلَى مَنْزِلِهِ ‏ ‏وَأَرْخَى السِّتْرَ بَيْنِي وَبَيْنَهُ وَأُنْزِلَتْ ‏ ‏آيَةُ الْحِجَابِ ‏","","",""],[11586,11586,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَرْمِي بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْفَعُ رَأْسَهُ مِنْ خَلْفِهِ لِيَنْظُرَ إِلَى مَوَاقِعِ نَبْلِهِ قَالَ فَتَطَاوَلَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏بِصَدْرِهِ ‏ ‏يَقِي بِهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ يَا رَسُولَ اللَّهِ نَحْرِي دُونَ نَحْرِكَ ‏","","",""],[11587,11587,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا أُخْبِرُكُمْ بِخَيْرِ دُورِ ‏ ‏الْأَنْصَارِ ‏ ‏دَارُ ‏ ‏بَنِي النَّجَّارِ ‏ ‏ثُمَّ دَارُ ‏ ‏بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏ثُمَّ دَارُ ‏ ‏بَنِي الْحَارِثِ بْنِ الْخَزْرَجِ ‏ ‏ثُمَّ دَارُ ‏ ‏بَنِي سَاعِدَةَ ‏ ‏وَفِي كُلِّ دُورِ ‏ ‏الْأَنْصَارِ ‏ ‏خَيْرٌ ‏","","",""],[11588,11588,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْدَمُ عَلَيْكُمْ أَقْوَامٌ هُمْ أَرَقُّ مِنْكُمْ قُلُوبًا قَالَ فَقَدِمَ ‏ ‏الْأَشْعَرِيُّونَ ‏ ‏فِيهِمْ ‏ ‏أَبُو مُوسَى الْأَشْعَرِيُّ ‏ ‏فَلَمَّا دَنَوْا مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏كَانُوا ‏ ‏يَرْتَجِزُونَ ‏ ‏يَقُولُونَ ‏ ‏غَدًا نَلْقَى ‏ ‏الْأَحِبَّهْ ‏ ‏مُحَمَّدًا ‏ ‏وَحِزْبَهْ ‏","","",""],[11589,11589,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ عِنْدَ بَعْضِ نِسَائِهِ قَالَ أَظُنُّهَا ‏ ‏عَائِشَةَ ‏ ‏فَأَرْسَلَتْ ‏ ‏إِحْدَى ‏ ‏أُمَّهَاتِ الْمُؤْمِنِينَ ‏ ‏مَعَ خَادِمٍ لَهَا ‏ ‏بِقَصْعَةٍ ‏ ‏فِيهَا طَعَامٌ قَالَ فَضَرَبَتْ الْأُخْرَى بِيَدِ الْخَادِمِ فَكُسِرَتْ ‏ ‏الْقَصْعَةُ ‏ ‏بِنِصْفَيْنِ قَالَ فَجَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏غَارَتْ أُمُّكُمْ قَالَ وَأَخَذَ الْكَسْرَتَيْنِ فَضَمَّ إِحْدَاهُمَا إِلَى الْأُخْرَى فَجَعَلَ فِيهَا الطَّعَامَ ثُمَّ قَالَ كُلُوا فَأَكَلُوا وَحَبَسَ الرَّسُولَ ‏ ‏وَالْقَصْعَةَ ‏ ‏حَتَّى فَرَغُوا فَدَفَعَ إِلَى الرَّسُولِ ‏ ‏قَصْعَةً ‏ ‏أُخْرَى وَتَرَكَ الْمَكْسُورَةَ مَكَانَهَا ‏","","",""],[11590,11590,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏اشْتَكَى ابْنٌ ‏ ‏لِأَبِي طَلْحَةَ ‏ ‏فَخَرَجَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏إِلَى الْمَسْجِدِ فَتُوُفِّيَ الْغُلَامُ فَهَيَّأَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏الْمَيِّتَ وَقَالَتْ لِأَهْلِهَا لَا يُخْبِرَنَّ أَحَدٌ مِنْكُمْ ‏ ‏أَبَا طَلْحَةَ ‏ ‏بِوَفَاةِ ابْنِهِ فَرَجَعَ إِلَى أَهْلِهِ وَمَعَهُ نَاسٌ مِنْ أَهْلِ الْمَسْجِدِ مِنْ أَصْحَابِهِ قَالَ مَا فَعَلَ الْغُلَامُ قَالَتْ خَيْرٌ مِمَّا كَانَ فَقَرَّبَتْ إِلَيْهِمْ عَشَاءَهُمْ فَتَعَشَّوْا وَخَرَجَ الْقَوْمُ وَقَامَتْ الْمَرْأَةُ إِلَى مَا تَقُومُ إِلَيْهِ الْمَرْأَةُ فَلَمَّا كَانَ آخِرُ اللَّيْلِ قَالَتْ يَا ‏ ‏أَبَا طَلْحَةَ ‏ ‏أَلَمْ تَرَ إِلَى آلِ فُلَانٍ اسْتَعَارُوا ‏ ‏عَارِيَةً ‏ ‏فَتَمَتَّعُوا بِهَا فَلَمَّا طُلِبَتْ كَأَنَّهُمْ كَرِهُوا ذَاكَ قَالَ مَا أَنْصَفُوا قَالَتْ فَإِنَّ ابْنَكَ كَانَ ‏ ‏عَارِيَةً ‏ ‏مِنْ اللَّهِ تَبَارَكَ وَتَعَالَى وَإِنَّ اللَّهَ قَبَضَهُ ‏ ‏فَاسْتَرْجَعَ ‏ ‏وَحَمِدَ اللَّهَ فَلَمَّا أَصْبَحَ غَدَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا رَآهُ قَالَ ‏ ‏بَارَكَ اللَّهُ لَكُمَا فِي لَيْلَتِكُمَا فَحَمَلَتْ ‏ ‏بِعَبْدِ اللَّهِ ‏ ‏فَوَلَدَتْهُ لَيْلًا وَكَرِهَتْ أَنْ ‏ ‏تُحَنِّكَهُ ‏ ‏حَتَّى ‏ ‏يُحَنِّكَهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَمَلْتُهُ ‏ ‏غُدْوَةً ‏ ‏وَمَعِي تَمَرَاتُ عَجْوَةٍ ‏ ‏فَوَجَدْتُهُ يَهْنَأُ أَبَاعِرَ لَهُ ‏ ‏أَوْ يَسِمُهَا ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏وَلَدَتْ اللَّيْلَةَ فَكَرِهَتْ أَنْ ‏ ‏تُحَنِّكَهُ ‏ ‏حَتَّى ‏ ‏يُحَنِّكَهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَمَعَكَ شَيْءٌ قُلْتُ تَمَرَاتُ عَجْوَةٍ فَأَخَذَ بَعْضَهُنَّ فَمَضَغَهُنَّ ثُمَّ جَمَعَ بُزَاقَهُ فَأَوْجَرَهُ إِيَّاهُ فَجَعَلَ ‏ ‏يَتَلَمَّظُ ‏ ‏فَقَالَ حُبُّ ‏ ‏الْأَنْصَارِ ‏ ‏التَّمْرَ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ سَمِّهِ قَالَ هُوَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏بُنْدَارٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏بَعْضَ هَذَا الْحَدِيثِ قَالَ فَأَتَيْتُهُ وَعَلَيْهِ ‏ ‏بُرْدَةٌ ‏ ‏حَدَّثَنَا ‏ ‏بُنْدَارٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏فَأَتَيْتُهُ وَعَلَيْهِ ‏ ‏خَمِيصَةٌ ‏ ‏لَهُ وَهُوَ فِي ‏ ‏الْحَائِطِ ‏ ‏يَسِمُ الظَّهْرَ الَّذِي قَدِمَ عَلَيْهِ فَقَالَ رُوَيْدَكَ أَفْرُغُ لَكَ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي عَدِىٍّ ‏ ‏فِي أَوَّلِ الْحَدِيثِ ‏ ‏إِنَّ ‏ ‏أَبَا طَلْحَةَ ‏ ‏غَدَا ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ بِتُّمَا عَرُوسَيْنِ قَالَ فَبَارَكَ اللَّهُ لَكُمَا فِي عُرْسِكُمَا وَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏لِأُمِّ سُلَيْمٍ ‏ ‏كَيْفَ ذَاكَ الْغُلَامُ قَالَتْ هُوَ أَهْدَأُ مِمَّا كَانَ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏تَزَوَّجَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏وَهِيَ أُمُّ ‏ ‏أَنَسٍ ‏ ‏وَالْبَرَاءِ ‏ ‏فَوَلَدَتْ لَهُ وَلَدًا وَكَانَ يُحِبُّهُ فَذَكَرَ الْحَدِيثَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبِتُّمَا عَرُوسَيْنِ وَهُوَ إِلَى جَنْبِكُمَا فَقَالَ نَعَمْ يَا رَسُولَ اللَّهِ قَالَ بَارَكَ اللَّهُ لَكُمَا فِي لَيْلَتِكُمَا ‏","","",""],[11591,11591,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏وَيَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏نُودِيَ بِالصَّلَاةِ فَقَامَ كُلُّ قَرِيبِ الدَّارِ مِنْ الْمَسْجِدِ وَبَقِيَ مَنْ كَانَ أَهْلُهُ نَائِيَ الدَّارِ ‏ ‏فَأُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِخْضَبٍ ‏ ‏مِنْ حِجَارَةٍ فَصَغُرَ أَنْ يَبْسُطَ أَكُفَّهُ فِيهِ قَالَ فَضَمَّ أَصَابِعَهُ قَالَ فَتَوَضَّأَ بَقِيَّتُهُمْ ‏ ‏قَالَ ‏ ‏حُمَيْدٌ ‏ ‏وَسُئِلَ ‏ ‏أَنَسٌ ‏ ‏كَمْ كَانُوا قَالَ ‏ ‏ثَمَانِينَ أَوْ زِيَادَةً ‏","","",""],[11592,11592,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏بَنِي سَلِمَةَ ‏ ‏أَرَادُوا أَنْ يَتَحَوَّلُوا مِنْ مَنَازِلِهِمْ فَيَسْكُنُوا قُرْبَ الْمَسْجِدِ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَرِهَ أَنْ ‏ ‏تُعْرَى ‏ ‏الْمَدِينَةُ ‏ ‏فَقَالَ يَا ‏ ‏بَنِي سَلِمَةَ ‏ ‏أَلَا تَحْتَسِبُونَ آثَارَكُمْ إِلَى الْمَسْجِدِ قَالُوا بَلَى يَا رَسُولَ اللَّهِ فَأَقَامُوا ‏","","",""],[11593,11593,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏وَسُهَيْلُ بْنُ يُوسُفَ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ فَجَاءَ رَجُلٌ ‏ ‏يَسْعَى ‏ ‏فَانْتَهَى وَقَدْ ‏ ‏حَفَزَهُ ‏ ‏النَّفَسُ أَوْ انْبَهَرَ فَلَمَّا انْتَهَى إِلَى الصَّفِّ قَالَ الْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ فَلَمَّا قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاتَهُ قَالَ أَيُّكُمْ الْمُتَكَلِّمُ فَسَكَتَ الْقَوْمُ فَقَالَ أَيُّكُمْ الْمُتَكَلِّمُ فَإِنَّهُ قَالَ خَيْرًا ‏ ‏أَوْ لَمْ يَقُلْ بَأْسًا ‏ ‏قَالَ يَا رَسُولَ اللَّهِ أَنَا أَسْرَعْتُ الْمَشْيَ فَانْتَهَيْتُ إِلَى الصَّفِّ فَقُلْتُ الَّذِي قُلْتُ قَالَ لَقَدْ ‏ ‏رَأَيْتُ اثْنَيْ عَشَرَ مَلَكًا يَبْتَدِرُونَهَا أَيُّهُمْ يَرْفَعُهَا ثُمَّ قَالَ إِذَا جَاءَ أَحَدُكُمْ إِلَى الصَّلَاةِ فَلْيَمْشِ عَلَى ‏ ‏هِينَتِهِ ‏ ‏فَلْيُصَلِّ مَا أَدْرَكَ وَلْيَقْضِ مَا سُبِقَهُ ‏","","",""],[11594,11594,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلْتُ الْجَنَّةَ فَسَمِعْتُ بَيْنَ يَدَيَّ ‏ ‏خَشْفَةً ‏ ‏فَإِذَا أَنَا ‏ ‏بِالْغُمَيْصَاءِ بِنْتِ مِلْحَانَ ‏","","",""],[11595,11595,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ اللَّهُ بِعَبْدٍ خَيْرًا اسْتَعْمَلَهُ قَالُوا وَكَيْفَ يَسْتَعْمِلُهُ قَالَ يُوَفِّقُهُ لِعَمَلٍ صَالِحٍ قَبْلَ مَوْتِهِ ‏","","",""],[11596,11596,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُؤْيَا الْمُؤْمِنِ جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنْ النُّبُوَّةِ ‏","","",""],[11597,11597,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا ‏ ‏يُهَادَى ‏ ‏بَيْنَ ابْنَيْهِ قَالَ مَا هَذَا قَالُوا نَذَرَ أَنْ يَمْشِيَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَغَنِيٌّ أَنْ يُعَذِّبَ هَذَا نَفْسَهُ فَأَمَرَهُ فَرَكِبَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى رَجُلًا ‏ ‏يُهَادَى ‏ ‏بَيْنَ ابْنَيْهِ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[11598,11598,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا يَسُوقُ ‏ ‏بَدَنَةً ‏ ‏قَدْ ‏ ‏جَهَدَهُ الْمَشْيُ فَقَالَ ارْكَبْهَا فَقَالَ يَا رَسُولَ اللَّهِ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ‏ ‏ارْكَبْهَا وَإِنْ كَانَتْ ‏ ‏بَدَنَةً ‏","","",""],[11599,11599,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلٌ يَسُوقُ ‏ ‏بِأُمَّهَاتِ الْمُؤْمِنِينَ يُقَالُ لَهُ ‏ ‏أَنْجَشَةُ ‏ ‏فَاشْتَدَّ فِي ‏ ‏السِّيَاقَةِ ‏ ‏فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أَنْجَشَةُ ‏ ‏رُوَيْدَكَ سَوْقًا ‏ ‏بِالْقَوَارِيرِ ‏","","",""],[11600,11600,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أَسْلَمَ نَاسٌ مِنْ ‏ ‏عُرَيْنَةَ ‏ ‏فَاجْتَوَوْا ‏ ‏الْمَدِينَةَ ‏ ‏فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ خَرَجْتُمْ إِلَى ‏ ‏ذَوْدٍ ‏ ‏لَنَا فَشَرِبْتُمْ مِنْ أَلْبَانِهَا ‏ ‏قَالَ ‏ ‏حُمَيْدٌ ‏ ‏وَقَالَ ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏وَأَبْوَالِهَا ‏ ‏فَفَعَلُوا فَلَمَّا ‏ ‏صَحُّوا ‏ ‏كَفَرُوا بَعْدَ إِسْلَامِهِمْ وَقَتَلُوا ‏ ‏رَاعِيَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُؤْمِنًا ‏ ‏أَوْ مُسْلِمًا ‏ ‏وَسَاقُوا ‏ ‏ذَوْدَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهَرَبُوا مُحَارِبِينَ فَأَرْسَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي آثَارِهِمْ فَأُخِذُوا ‏ ‏فَقَطَّعَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ ‏ ‏وَسَمَرَ ‏ ‏أَعْيُنَهُمْ وَتَرَكَهُمْ فِي ‏ ‏الْحَرَّةِ ‏ ‏حَتَّى مَاتُوا ‏","","",""]];
